const S = {me:null,dash:null,project:null,view:'home',tab:'overview',space:'work',modal:null,query:'',filter:'all',aiResult:null,aiType:'ideas',aiPrompt:'',online:true,pending:false,stream:null,toastTimer:null,searchResults:null,noticeData:null,trashData:null,historyData:null,archiveData:null,knowledgeData:null,analyticsData:null,guardianData:null,analyticsSpace:"all"};
const $=s=>document.querySelector(s);
const e=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const iconPaths={home:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',briefcase:'<rect x="3" y="7" width="18" height="14" rx="2"/><path d="M8 7V5a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2M3 12h18"/>',heart:'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 10h18"/>',activity:'<path d="M3 12h4l3-8 4 16 3-8h4"/>',spark:'<path d="m12 3 2.2 6.8L21 12l-6.8 2.2L12 21l-2.2-6.8L3 12l6.8-2.2L12 3Z"/>',settings:'<circle cx="12" cy="12" r="3"/><path d="M19.5 12a7 7 0 0 0-.1-1.1l2-1.6-2-3.5-2.4 1a8 8 0 0 0-1.8-1L14.8 3h-4l-.4 2.8a8 8 0 0 0-1.8 1l-2.4-1-2 3.5 2 1.6a8 8 0 0 0 0 2.2l-2 1.6 2 3.5 2.4-1a8 8 0 0 0 1.8 1l.4 2.8h4l.4-2.8a8 8 0 0 0 1.8-1l2.4 1 2-3.5-2-1.6c.1-.4.1-.7.1-1.1Z"/>',plus:'<path d="M12 5v14M5 12h14"/>',arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',back:'<path d="m15 18-6-6 6-6"/>',check:'<path d="m4 12 5 5L20 6"/>',checkcircle:'<circle cx="12" cy="12" r="9"/><path d="m8 12 3 3 5-6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',users:'<circle cx="9" cy="8" r="3"/><path d="M2 20v-2a5 5 0 0 1 5-5h4a5 5 0 0 1 5 5v2M17 5a3 3 0 0 1 0 6m2 3a5 5 0 0 1 3 4v2"/>',file:'<path d="M6 3h8l5 5v13H6a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2ZM14 3v6h5"/><path d="M8 14h8M8 18h6"/>',message:'<path d="M21 11.5a8.5 8.5 0 0 1-8.5 8.5 9 9 0 0 1-4-.9L3 21l1.8-5.4a8.5 8.5 0 1 1 16.2-4.1Z"/>',link:'<path d="M10 13a5 5 0 0 0 7.1 0l3-3a5 5 0 0 0-7.1-7.1l-1.7 1.7M14 11a5 5 0 0 0-7.1 0l-3 3a5 5 0 1 0 7.1 7.1l1.7-1.7"/>',folder:'<path d="M3 6a2 2 0 0 1 2-2h5l2 2h7a2 2 0 0 1 2 2v11a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2Z"/>',more:'<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>',trash:'<path d="M4 7h16M10 4h4M6 7l1 14h10l1-14M10 11v6m4-6v6"/>',edit:'<path d="m16 4 4 4-12 12H4v-4L16 4Zm0 0 2-2 4 4-2 2"/>',close:'<path d="m5 5 14 14M19 5 5 19"/>',logout:'<path d="M10 4H5a2 2 0 0 0-2 2v12a2 2 0 0 0 2 2h5m4-16 7 8-7 8m7-8H9"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M5 17v4h14v-4"/>',upload:'<path d="M12 16V4m-5 5 5-5 5 5M5 16v5h14v-5"/>',globe:'<circle cx="12" cy="12" r="9"/><path d="M3 12h18M12 3a15 15 0 0 1 0 18M12 3a15 15 0 0 0 0 18"/>',search:'<circle cx="11" cy="11" r="7"/><path d="m16 16 5 5"/>',chevron:'<path d="m9 18 6-6-6-6"/>',layers:'<path d="m12 2 9 5-9 5-9-5 9-5Zm-9 10 9 5 9-5M3 17l9 5 9-5"/>',coffee:'<path d="M4 8h13v6a6 6 0 0 1-6 6H9a5 5 0 0 1-5-5V8Zm13 1h3a3 3 0 0 1 0 6h-3M7 3v2m5-2v2"/>',pin:'<path d="M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="2.5"/>',refresh:'<path d="M21 7v5h-5M3 17v-5h5M5 9a8 8 0 0 1 14-2l2 5M3 12l2 5a8 8 0 0 0 14-2"/>',external:'<path d="M14 4h6v6m0-6-9 9M20 14v5a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V6a2 2 0 0 1 2-2h5"/>',alert:'<path d="M12 3 2 21h20L12 3Zm0 7v5m0 3v.1"/>',inbox:'<rect x=3 y=4 width=18 height=16 rx=2/><path d="M3 13h5l2 3h4l2-3h5"/>',bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 8-3 9h18c0-1-3-2-3-9M10 21h4"/>',undo:'<path d="M9 14 4 9l5-5M4 9h10a7 7 0 0 1 0 14"/>',menu:'<path d="M3 6h18M3 12h18M3 18h18"/>'};
function I(name,size=19){return `<svg class="ic" width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${iconPaths[name]||iconPaths.folder}</svg>`;}
const STATUS={idea:'Idea',planning:'Planificando',active:'En marcha',done:'Finalizado'};
const STATUS_ICON={idea:'spark',planning:'layers',active:'activity',done:'checkcircle'};
const SPACES={work:{name:'Trabajo',full:'Proyectos de trabajo',sub:'Todo lo que construimos juntos.',icon:'briefcase',article:'profesional',em:'Ideas que se convierten en realidad.'},couple:{name:'Planes en común',full:'Planes en común',sub:'Viajes, experiencias e ideas nuestras.',icon:'heart',article:'personal',em:'Una vida llena de planes por vivir y crear.'}};
const fmt=d=>d?new Date(d.length===10?d+'T12:00:00':d).toLocaleDateString('es-ES',{day:'numeric',month:'short',year:'numeric'}):'Sin fecha';
const short=d=>d?new Date(d.length===10?d+'T12:00:00':d).toLocaleDateString('es-ES',{day:'numeric',month:'short'}):'Ahora';
const initials=n=>String(n||'·').split(' ').filter(Boolean).slice(0,2).map(x=>x[0]).join('').toUpperCase();
const pct=(done,total)=>total?Math.round(done/total*100):0;
const avatar=(name,cls='')=>`<span class="avatar ${cls}" title="${e(name)}">${e(initials(name))}</span>`;
const colorTag=c=>['indigo','rose','emerald','amber','sky','violet'].includes(c)?c:'indigo';
const capitalize=s=>s.charAt(0).toUpperCase()+s.slice(1);
async function api(path,method='GET',body){const opts={method,headers:{}};if(body!==undefined){opts.headers['Content-Type']='application/json';opts.body=JSON.stringify(body);}const r=await fetch(path,opts);let json;try{json=await r.json();}catch{json={error:'Respuesta inesperada'};}if(!r.ok){if(r.status===401){S.me=null;S.stream?.close();renderLogin();}const ex=new Error(json.error||`Error ${r.status}`);ex.status=r.status;ex.latest=json.latest;throw ex;}return json;}
function toast(msg,kind='ok'){const el=$('#toast');el.textContent=msg;el.className='toast show '+kind;clearTimeout(S.toastTimer);S.toastTimer=setTimeout(()=>el.classList.remove('show'),4700);}
async function loadDash(){S.dash=await api('/api/dashboard');}
async function loadProject(id){S.project=(await api('/api/projects/'+id)).project;}
function nav(view){S.view=view;S.project=null;S.modal=null;S.aiResult=null;S.query='';S.filter='all';render();window.scrollTo(0,0);}
async function openProject(id){try{await loadProject(id);S.view='project';S.tab='overview';S.modal=null;S.aiResult=null;render();window.scrollTo(0,0);}catch(ex){toast(ex.message,'error');}}
async function updateAfter(projectId){await loadDash();if(S.view==='notices')S.noticeData=await api('/api/notifications');if(S.view==='trash')S.trashData=await api('/api/trash');if(S.view==='archives')S.archiveData=await api('/api/archives');if(S.view==='knowledge')S.knowledgeData=await api('/api/knowledge');if(S.view==='intelligence')S.analyticsData=await api('/api/analytics?space='+encodeURIComponent(S.analyticsSpace==='all'?'':S.analyticsSpace));if(S.view==='guardian')S.guardianData=await api('/api/guardian/report');if(projectId&&S.view==='project'&&S.project?.id===projectId)await loadProject(projectId);render();}
function conn(){S.stream?.close();const es=new EventSource('/api/stream');S.stream=es;es.onopen=()=>{S.online=true;updateConnection();};es.onerror=()=>{S.online=false;updateConnection();};es.addEventListener('change',async(ev)=>{const msg=JSON.parse(ev.data);if(msg.actor===S.me.id)return;if(S.modal||document.activeElement?.matches('textarea,input,[contenteditable]')){S.pending=true;updateConnection();toast('Hay cambios de la otra persona. Pulsa Actualizar.','info');return;}try{await updateAfter(S.project?.id);toast('Cambios compartidos actualizados.','info');}catch(ex){if(ex.status===404){await loadDash();nav('home');toast('El proyecto ha sido eliminado por la otra persona.','info');}else console.error(ex);}});}
function updateConnection(){const x=$('#live-status');if(x)x.innerHTML=`<span class="live-dot ${S.online?'':'offline'}"></span> ${S.pending?'Cambios nuevos · actualizar':S.online?'Sincronización activa':'Reconectando…'}`;}
function renderSetup(enabled){const app=$('#app');app.innerHTML=`<div class="login-screen"><div class="login-aside"><div class="brand large"><div class="brand-mark">d<span>·</span></div><span>DOS ESPACIOS</span></div><div class="login-story"><span class="eyebrow light">PRIMER ACCESO · PRIVADO</span><h1>Dos personas.<br/>Un mismo<br/><i>espacio.</i></h1><p>Configurad vuestras dos cuentas una sola vez. Todo lo que creéis será compartido.</p></div><div class="login-footer">Álvaro & Angie · Acceso privado</div></div><main class="login-main"><div class="login-box"><span class="eyebrow">ACTIVACIÓN DE VUESTRO ESPACIO</span><h2>Vamos a empezar juntos.</h2>${enabled?`<p>Introduce la clave secreta definida en el alojamiento y las credenciales de los dos. Este formulario solo está disponible antes de crear las cuentas.</p><form id="setup-form" class="stack-form"><label>Clave de instalación<input type="password" name="setup_token" required minlength="32" autocomplete="off" placeholder="La clave de Railway"/></label><label>Correo de Álvaro<input type="email" name="email_a" required autocomplete="off"/></label><label>Contraseña de Álvaro (mínimo 12 caracteres)<input type="password" name="password_a" required minlength="12" autocomplete="new-password"/></label><label>Correo de Angie<input type="email" name="email_b" required autocomplete="off"/></label><label>Contraseña de Angie (mínimo 12 caracteres)<input type="password" name="password_b" required minlength="12" autocomplete="new-password"/></label><button class="btn primary full" type="submit">Crear nuestras dos cuentas ${I('arrow',18)}</button><p class="form-error" id="setup-error" role="alert"></p></form>`:`<p>El servidor todavía no tiene cuentas. Para permitir la activación web, configura un secreto aleatorio de 32 caracteres o más en la variable <strong>SETUP_TOKEN</strong> del alojamiento y reinicia la aplicación. También puedes usar <code>npm run setup</code> desde el servidor.</p><button class="btn outline" onclick="location.reload()">Comprobar configuración</button>`}<div class="private-note">${I('users',16)} No compartáis las claves en ChatGPT. Guardadlas en vuestro gestor de contraseñas.</div></div></main></div>`;
const form=$('#setup-form');if(form)form.addEventListener('submit',async ev=>{ev.preventDefault();const data=Object.fromEntries(new FormData(form));const btn=form.querySelector('button');btn.disabled=true;btn.textContent='Creando cuentas…';try{await api('/api/initialize','POST',data);renderLogin();toast('¡Cuentas creadas! Inicia sesión.','info');}catch(ex){$('#setup-error').textContent=ex.message;}finally{btn.disabled=false;btn.innerHTML='Crear nuestras dos cuentas '+I('arrow',18);}});
}
function renderLogin(){const app=$('#app');app.innerHTML=`<div class="login-screen"><div class="login-aside"><div class="brand large"><div class="brand-mark">d<span>·</span></div><span>DOS ESPACIOS</span></div><div class="login-story"><span class="eyebrow light">UN LUGAR. DOS PERSONAS.</span><h1>Nuestras ideas<br/>merecen un<br/><i>lugar propio.</i></h1><p>El espacio privado donde trabajo y vida en común encuentran su sitio.</p><div class="login-chips"><span>${I('briefcase',16)} Lo que construimos</span><span>${I('heart',16)} Lo que vivimos</span></div></div><div class="login-footer">Hecho exclusivamente para vosotros dos ✦</div></div><main class="login-main"><div class="login-box"><span class="eyebrow">BIENVENIDOS A VUESTRO ESPACIO</span><h2>Qué bien tenerte aquí.</h2><p>Inicia sesión para volver a todo lo que estáis construyendo juntos.</p><form id="login-form" class="stack-form"><label>Correo electrónico<input type="email" name="email" required autocomplete="email" placeholder="tu@correo.com" /></label><label>Contraseña<input type="password" name="password" required autocomplete="current-password" placeholder="Tu contraseña" /></label><button class="btn primary full" type="submit">Entrar en nuestro espacio ${I('arrow',18)}</button><p id="login-error" class="form-error"></p></form><div class="private-note">${I('users',16)} Acceso exclusivamente para Álvaro y Angie. Sin registro público.</div></div></main></div>`;$('#login-form').addEventListener('submit',async ev=>{ev.preventDefault();const f=new FormData(ev.target);const b=ev.target.querySelector('button');b.disabled=true;b.textContent='Entrando…';try{const r=await api('/api/login','POST',{email:f.get('email'),password:f.get('password')});S.me=r.user;await loadDash();conn();render();}catch(ex){$('#login-error').textContent=ex.message;}finally{b.disabled=false;b.innerHTML='Entrar en nuestro espacio '+I('arrow',18);}});}
function sidebar(){return `<aside class="sidebar" id="sidebar"><div class="sidebar-inner"><div class="brand"><div class="brand-mark">d<span>·</span></div><div class="brand-text">DOS <small>ESPACIOS</small></div></div><div class="side-group"><div class="side-label">VUESTRO LUGAR</div><button class="nav-item ${S.view==='home'?'active':''}" data-nav="home">${I('home')} <span>Inicio</span></button><div class="side-label second">LOS DOS UNIVERSOS</div><button class="nav-item ${S.view==='work' ||(S.view==='project'&&S.project?.space==='work')?'active work-nav':''}" data-nav="work">${I('briefcase')} <span>Trabajo</span><small>${S.dash?.projects.filter(p=>p.space==='work'&&!p.archived).length||0}</small></button><button class="nav-item ${S.view==='couple'||(S.view==='project'&&S.project?.space==='couple')?'active couple-nav':''}" data-nav="couple">${I('heart')} <span>Planes en común</span><small>${S.dash?.projects.filter(p=>p.space==='couple'&&!p.archived).length||0}</small></button><div class="side-label second">HERRAMIENTAS</div><button class="nav-item ${S.view==='ideas'?'active':''}" data-nav="ideas">${I('inbox')} <span>Buzón de ideas</span><small>${S.dash?.ideas?.filter(i=>i.state!=='converted').length||0}</small></button><button class="nav-item ${S.view==='search'?'active':''}" data-nav="search">${I('search')} <span>Buscar en todo</span></button><button class="nav-item ${S.view==='knowledge'?'active':''}" data-nav="knowledge">${I('file')} <span>Biblioteca de conocimiento</span></button><button class="nav-item ${S.view==='intelligence'?'active':''}" data-nav="intelligence">${I('activity')} <span>Datos e inteligencia</span></button><button class="nav-item ${S.view==='guardian'?'active':''}" data-nav="guardian">${I('settings')} <span>Director General</span></button><button class="nav-item ${S.view==='notices'?'active':''}" data-nav="notices">${I('bell')} <span>Notificaciones</span><small>${S.dash?.unread||0}</small></button><button class="nav-item ${S.view==='dates'?'active':''}" data-nav="dates">${I('calendar')} <span>Fechas y planes</span></button><button class="nav-item ${S.view==='activity'?'active':''}" data-nav="activity">${I('activity')} <span>Actividad</span></button><button class="nav-item ${S.view==='connections'?'active':''}" data-nav="connections">${I('spark')} <span>Conexiones IA</span></button></div><div class="side-bottom"><div class="side-tip"><div class="tip-star">✳</div><strong>Un proyecto, dos miradas.</strong><span>Cualquier cambio se comparte automáticamente.</span></div><button class="nav-item" data-nav="settings">${I('settings')} <span>Ajustes</span></button><div class="profile"><span class="avatar avatar-profile">${e(initials(S.me.name))}</span><div><b>${e(S.me.name)}</b><small>Mi espacio compartido</small></div><button class="icon-btn profile-out" data-action="logout" title="Salir">${I('logout',17)}</button></div></div></div></aside>`;}
function header(){const title=S.view==='home'?'Nuestro rincón':S.view==='project'?(S.project?.space==='work'?'Trabajo':'Planes'):{work:'Trabajo',couple:'Planes en común',ideas:'Buzón de ideas',search:'Buscar en todo',notices:'Notificaciones',trash:'Papelera',archives:'Archivados',dates:'Fechas y planes',activity:'Actividad',connections:'Conexiones',knowledge:'Conocimiento',intelligence:'Datos e inteligencia',guardian:'Director General',settings:'Ajustes'}[S.view];return `<header class="topbar"><div class="topbar-left"><button class="icon-btn mobile-menu" data-action="toggle-menu" aria-label="Abrir menú">${I('menu',21)}</button><span class="topbar-path">DOS ESPACIOS</span>${I('chevron',13)}<b>${e(title||'')}</b></div><div class="topbar-right"><button id="live-status" class="live-status" data-action="sync"><span class="live-dot"></span> Sincronización activa</button><div class="top-avatars">${(S.dash?.users||[]).map((u,i)=>avatar(u.name,i===0?'av-first':'av-second')).join('')}</div><span class="divider-vert"></span><span class="top-profile">Hola, ${e(S.me.name.split(' ')[0])} <span class="wave">✳</span></span></div></header>`;}
function render(){if(!S.me)return renderLogin();$('#app').innerHTML=`<div class="shell">${sidebar()}<div class="workspace">${header()}<main class="content" id="content">${content()}</main><footer class="site-footer">DOS ESPACIOS <span>✦</span> Álvaro & Angie · Lo nuestro, a nuestra manera.</footer></div></div><div id="modal-root">${S.modal?modalHTML():''}</div>`;updateConnection();bindGlobal();}
function content(){switch(S.view){case 'work':return spacePage('work');case 'couple':return spacePage('couple');case 'project':return projectPage();case 'ideas':return ideasPage();case 'search':return searchPage();case 'notices':return notificationsPage();case 'knowledge':return knowledgePage();case 'intelligence':return intelligencePage();case 'guardian':return guardianPage();case 'trash':return trashPage();case 'archives':return archivesPage();case 'dates':return datesPage();case 'activity':return activityPage();case 'connections':return connectionsPage();case 'settings':return settingsPage();default:return homePage();}}
function kpi(icon,title,n,tag){return `<div class="kpi"><span class="kpi-icon">${I(icon,20)}</span><div><span>${e(title)}</span><b>${n}</b></div><small>${e(tag)}</small></div>`;}
function hello(){const h=new Date().getHours();return h<13?'Buenos días':h<20?'Buenas tardes':'Buenas noches';}
function homePage(){const projects=S.dash.projects.filter(p=>!p.archived),active=projects.filter(p=>p.status==='active').length,ideas=projects.filter(p=>p.status==='idea').length;
 const tasks=projects.reduce((n,p)=>n+p.tasks_total,0),done=projects.reduce((n,p)=>n+p.tasks_done,0),upcoming=S.dash.upcoming.filter(x=>x.date>=new Date().toISOString().slice(0,10)).slice(0,5);
 return `<div class="page"><div class="welcome-block"><div><div class="eyebrow"><span class="mini-spark">✦</span> VUESTRO ESPACIO COMPARTIDO</div><h1>${hello()}, ${e(S.me.name.split(' ')[0])}<span class="title-dot">.</span></h1><p>Todo lo que soñáis, planificáis y hacéis juntos. En un solo lugar.</p></div><button class="btn outline" data-action="new-project">${I('plus',17)} Nueva idea o proyecto</button></div><div class="home-banner"><div class="home-banner-text"><span class="eyebrow light">DOS UNIVERSOS, UN SOLO EQUIPO</span><h2>Juntos, las buenas ideas<br/>llegan más lejos.</h2><p>Desde vuestra próxima aventura hasta el próximo gran proyecto.</p></div><div class="banner-art"><div class="orb orb-a"></div><div class="orb orb-b"></div><span>dos<span>.</span></span><div class="orbit-line"></div></div></div><div class="quick-inbox"><span>${I('inbox',19)} ¿Una idea que no queréis olvidar?</span><button class="btn primary" data-action="new-idea">${I('plus',16)} Capturar idea</button><button class="btn outline" data-nav="ideas">Abrir buzón ${I('arrow',16)}</button></div><div class="stat-grid">${kpi('layers','Proyectos compartidos',projects.length,'Siempre entre los dos')}${kpi('activity','En marcha',active,'Avanzando juntos')}${kpi('spark','Ideas guardadas',ideas,'A la espera de crecer')}${kpi('checkcircle','Tareas completadas',`${done}/${tasks}`,'Pequeñas victorias')}</div><div class="section-heading"><div><span class="eyebrow">¿DÓNDE SEGUIMOS?</span><h2>Vuestros dos espacios</h2></div></div><div class="space-tiles"><button class="space-tile tile-work" data-nav="work"><div class="tile-head"><span class="tile-icon">${I('briefcase',25)}</span><span class="tile-index">01 / PROFESIONAL</span></div><div><h3>Trabajo <span>↗</span></h3><p>Ideas, aplicaciones, campañas, planes, tareas y proyectos para construir juntos.</p></div><div class="tile-foot"><span>${projects.filter(p=>p.space==='work').length} proyectos conjuntos</span>${I('arrow',20)}</div></button><button class="space-tile tile-couple" data-nav="couple"><div class="tile-head"><span class="tile-icon">${I('heart',25)}</span><span class="tile-index">02 / NUESTRA VIDA</span></div><div><h3>Planes en común <span>↗</span></h3><p>Viajes, cenas, citas, sorpresas, ideas y todos los planes que nos unen.</p></div><div class="tile-foot"><span>${projects.filter(p=>p.space==='couple').length} proyectos juntos</span>${I('arrow',20)}</div></button></div><div class="columns-2"><section class="panel"><div class="panel-title"><div><span class="eyebrow">DE UN VISTAZO</span><h3>Movimientos recientes</h3></div><button class="text-btn" data-nav="activity">Ver todo ${I('arrow',15)}</button></div>${recentHtml(S.dash.recent.slice(0,6))}</section><section class="panel"><div class="panel-title"><div><span class="eyebrow">PARA NO OLVIDAR</span><h3>Próximas fechas</h3></div><button class="text-btn" data-nav="dates">Ver agenda ${I('arrow',15)}</button></div>${upcoming.length?upcoming.map(upcomingLine).join(''):`<div class="empty-mini">${I('calendar',26)}<p>Aún no hay fechas próximas. Añade tareas o planes a un proyecto.</p></div>`}</section></div></div>`;}
function recentHtml(items){return items?.length?`<div class="activity-list">${items.map(a=>`<button class="activity-line" data-project="${a.project_id||''}"><span class="mini-ava">${e(initials(a.author||'?'))}</span><div><p><b>${e(a.author||'Alguien')}</b> ${e(a.action)} ${a.detail?`<strong>${e(a.detail)}</strong>`:''}</p><small>${e(a.project_title|| (a.space==='work'?'Trabajo':'Planes'))} · ${fmt(a.created_at)}</small></div><span class="activity-time">${new Date(a.created_at).toLocaleTimeString('es-ES',{hour:'2-digit',minute:'2-digit'})}</span></button>`).join('')}</div>`:'<div class="empty-mini">Aún no hay actividad. Vuestra primera idea está esperando.</div>';}
function upcomingLine(x){return `<button class="upcoming" data-project="${x.project_id}"><div class="date-chip"><b>${new Date(x.date+'T12:00:00').getDate()}</b><small>${new Date(x.date+'T12:00:00').toLocaleDateString('es-ES',{month:'short'})}</small></div><div class="upcoming-info"><b>${e(x.title)}</b><span>${e(x.project_title)}</span></div><span class="space-pill ${x.space}">${x.space==='work'?'Trabajo':'Planes'}</span></button>`;}
function progressHtml(done,total){return `<div class="progress"><div style="width:${pct(done,total)}%"></div></div>`;}
function projectCard(p){return `<button class="project-card" data-project="${p.id}"><div class="card-top"><span class="project-icon ${colorTag(p.color)}">${I(p.space==='work'?'briefcase':'heart',21)}</span><span class="status status-${p.status}">${I(STATUS_ICON[p.status],13)} ${STATUS[p.status]}</span></div><h3>${e(p.title)}</h3><p>${e(p.description||'Un espacio listo para desarrollar esta idea entre los dos.')}</p><div class="card-bottom"><div class="card-progress"><div class="progress-label"><span>${p.tasks_done}/${p.tasks_total} tareas</span><b>${pct(p.tasks_done,p.tasks_total)}%</b></div>${progressHtml(p.tasks_done,p.tasks_total)}</div><div class="card-bottom-row"><div class="avatar-stack">${S.dash.users.map((u,i)=>avatar(u.name,i===0?'av-first':'av-second')).join('')}</div><span>${I('clock',13)} ${short(p.updated_at)}</span><span class="card-go">${I('arrow',17)}</span></div></div></button>`;}
function renderCards(){const root=$('#project-grid');if(!root)return;const projects=S.dash.projects.filter(p=>p.space===S.space&&!p.archived&&(S.filter==='all'||p.status===S.filter)&&(!S.query||(p.title+' '+p.description).toLocaleLowerCase('es').includes(S.query.toLocaleLowerCase('es'))));root.innerHTML=projects.length?projects.map(projectCard).join(''):`<div class="empty-grid"><div class="empty-icon">${I('spark',30)}</div><h3>Este espacio está listo para empezar.</h3><p>${S.query||S.filter!=='all'?'No hay resultados con esos filtros.':'Cread vuestra primera idea, añadid tareas y desarrolladla juntos.'}</p><button class="btn primary" data-action="new-project" data-space="${S.space}">${I('plus',17)} Crear proyecto</button></div>`;}
function spacePage(space){S.space=space;const s=SPACES[space];const projects=S.dash.projects.filter(p=>p.space===space&&!p.archived);
 const filtered=projects.filter(p=>(S.filter==='all'||p.status===S.filter)&&(!S.query||(p.title+' '+p.description).toLocaleLowerCase('es').includes(S.query.toLocaleLowerCase('es'))));
 return `<div class="page"><div class="space-hero ${space}"><div class="space-hero-content"><button class="back-link" data-nav="home">${I('back',15)} Inicio / ${s.name}</button><span class="eyebrow ${space==='work'?'':'light'}">${space==='work'?'CREAMOS JUNTOS':'VIVIMOS JUNTOS'} ✦</span><h1>${e(s.full)}<span class="title-dot">.</span></h1><p>${e(s.em)} Todo lo que hay aquí nos pertenece a los dos.</p><div class="space-count">${I('users',16)} ${projects.length} proyectos compartidos · Álvaro + Angie</div></div><div class="space-hero-symbol">${I(s.icon,78)}</div></div><div class="section-heading projects-heading"><div><span class="eyebrow">IDEAS Y PROYECTOS</span><h2>Todo lo que tenemos entre manos</h2></div><button class="btn primary" data-action="new-project" data-space="${space}">${I('plus',17)} Crear proyecto</button></div><div class="toolbar"><div class="search-box">${I('search',18)}<input id="project-search" placeholder="Buscar entre vuestras ideas…" value="${e(S.query)}" autocomplete="off"/></div><div class="filter-list">${[['all','Todos'],['idea','Ideas'],['planning','Planificando'],['active','En marcha'],['done','Finalizados']].map(([k,v])=>`<button data-filter="${k}" class="filter-chip ${S.filter===k?'selected':''}">${v}</button>`).join('')}</div></div><div class="project-grid" id="project-grid">${filtered.length?filtered.map(projectCard).join(''):`<div class="empty-grid"><div class="empty-icon">${I('spark',30)}</div><h3>Este espacio está listo para empezar.</h3><p>${S.query||S.filter!=='all'?'No hay resultados con esos filtros.':'Cread vuestra primera idea, añadid tareas y desarrolladla juntos.'}</p><button class="btn primary" data-action="new-project" data-space="${space}">${I('plus',17)} Crear proyecto</button></div>`}</div></div>`;}
function tabButton(k,name,icon,n){return `<button class="project-tab ${S.tab===k?'on':''}" data-tab="${k}">${I(icon,17)} ${name} ${n!==undefined?`<small>${n}</small>`:''}</button>`;}
function projectPage(){const p=S.project;if(!p)return '';const done=p.tasks.filter(t=>t.state==='done').length;return `<div class="page project-page"><button class="back-link dark" data-nav="${p.space}">${I('back',16)} Volver a ${SPACES[p.space].name}</button><div class="project-main-head"><div class="project-identity"><span class="project-icon large ${colorTag(p.color)}">${I(p.space==='work'?'briefcase':'heart',27)}</span><div><div class="eyebrow">${p.space==='work'?'PROYECTO DE TRABAJO CONJUNTO':'PROYECTO EN COMÚN · COMPARTIDO'}</div><h1>${e(p.title)}</h1><div class="head-meta"><span class="status status-${p.status}">${I(STATUS_ICON[p.status],14)} ${STATUS[p.status]}</span><span>${I('clock',14)} Actualizado ${fmt(p.updated_at)}</span></div></div></div><div class="project-actions"><button class="btn outline" data-action="print-project">${I('download',16)} Informe PDF</button><button class="btn outline" data-action="edit-project">${I('edit',17)} Editar proyecto</button><button class="btn primary" data-action="new-task">${I('plus',17)} Nueva tarea</button></div></div><div class="project-tabs">${tabButton('overview','Resumen','home')}${tabButton('tasks','Tareas','checkcircle',p.tasks.length)}${tabButton('roadmap','Hoja de ruta','layers',p.milestones.length)}${tabButton('decisions','Decisiones','users',p.decisions?.length||0)}${tabButton('notes','Notas y diseño','file',p.sections.length)}${tabButton('dates','Planes y fechas','calendar',p.events.length)}${tabButton('budget','Presupuesto','coffee',p.expenses.length)}${tabButton('files','Archivos y enlaces','folder',p.assets.length+p.links.length)}${tabButton('chat','Conversación','message',p.comments.length)}${tabButton('activity','Historial','activity')}${p.space==='work'?tabButton('ai','Laboratorio IA','spark'):''}</div><div class="tab-body">${projectContent()}</div></div>`;}
function projectContent(){switch(S.tab){case 'tasks':return tasksTab();case 'roadmap':return roadmapTab();case 'decisions':return decisionsTab();case 'budget':return budgetTab();case 'notes':return notesTab();case 'dates':return projectDatesTab();case 'files':return filesTab();case 'chat':return chatTab();case 'activity':return projectActivityTab();case 'ai':return aiTab();default:return overviewTab();}}
function overviewTab(){const p=S.project,done=p.tasks.filter(t=>t.state==='done').length,total=p.tasks.length;return `<div class="project-overview"><div class="overview-main"><section class="panel large-panel"><div class="panel-title"><div><span class="eyebrow">LA IDEA</span><h3>¿De qué va este proyecto?</h3></div><button class="icon-btn" data-action="edit-project" title="Editar">${I('edit',18)}</button></div><p class="project-description">${e(p.description||'Todavía no habéis escrito una descripción. Podéis contar aquí cuál es el objetivo, qué queréis crear o cómo os imagináis este plan.')}</p><div class="tags-row"><span class="tag">${I('users',14)} Los dos</span><span class="tag">${I('clock',14)} Creado ${fmt(p.created_at)}</span></div></section><section class="panel"><div class="panel-title"><div><span class="eyebrow">EN QUÉ ANDAMOS</span><h3>Próximas tareas</h3></div><button class="text-btn" data-tab="tasks">Ver todas ${I('arrow',15)}</button></div>${p.tasks.filter(t=>t.state!=='done').slice(0,5).map(taskLine).join('')||'<div class="empty-mini">Todo al día. Añadid la siguiente tarea.</div>'}<button class="link-add" data-action="new-task">${I('plus',16)} Añadir tarea</button></section><section class="panel"><div class="panel-title"><div><span class="eyebrow">PONER LAS IDEAS EN ORDEN</span><h3>Notas y desarrollo</h3></div><button class="text-btn" data-tab="notes">Abrir notas ${I('arrow',15)}</button></div>${p.sections.slice(0,3).map(n=>`<button class="note-preview" data-action="edit-section" data-id="${n.id}"><span>${I('file',17)}</span><div><b>${e(n.title)}</b><small>${e((n.content||'Nota vacía').slice(0,90))}</small></div>${I('chevron',16)}</button>`).join('')||'<div class="empty-mini">Guardad decisiones, ideas, bocetos o referencias aquí.</div>'}<button class="link-add" data-action="new-section">${I('plus',16)} Nueva nota</button></section></div><div class="overview-side"><section class="panel progress-panel"><div class="eyebrow">VUESTRO PROGRESO</div><div class="big-percent">${pct(done,total)}<small>%</small></div><p>de las tareas completadas</p>${progressHtml(done,total)}<div class="progress-stats"><span>${done} completadas</span><span>${total-done} pendientes</span></div></section><section class="panel"><div class="panel-title"><div><span class="eyebrow">LOS DOS</span><h3>Equipo</h3></div></div>${S.dash.users.map((u,i)=>`<div class="member-line">${avatar(u.name,i===0?'av-first':'av-second')}<div><b>${e(u.name)}</b><small>${u.id===S.me.id?'Estás aquí':'Colaboración completa'}</small></div><span class="member-access">Editor/a</span></div>`).join('')}<div class="privacy-note">${I('checkcircle',16)} Todo este proyecto está compartido con ambos.</div></section><section class="panel"><div class="panel-title"><div><span class="eyebrow">PRÓXIMAMENTE</span><h3>Fechas importantes</h3></div><button class="text-btn" data-tab="dates">Ver planes ${I('arrow',15)}</button></div>${p.events.slice(0,3).map(x=>`<div class="simple-event"><span>${I('calendar',17)}</span><div><b>${e(x.title)}</b><small>${fmt(x.event_date)}</small></div></div>`).join('')||'<div class="empty-mini">Todavía no hay fechas.</div>'}</section></div></div>`;}
function taskLine(t){return `<div class="task-line"><button class="task-check ${t.state==='done'?'is-done':''}" data-action="quick-task" data-id="${t.id}" title="Completar">${t.state==='done'?I('check',15):''}</button><button class="task-line-main" data-action="edit-task" data-id="${t.id}"><b>${e(t.title)}</b><small>${t.due_date?I('calendar',13)+' '+fmt(t.due_date):'Sin fecha'} ${t.priority==='high'?' · Prioridad alta':''}</small></button>${t.assigned_to?avatar(S.dash.users.find(u=>u.id===t.assigned_to)?.name||'?','tiny'):''}</div>`;}
function tasksTab(){const p=S.project;return `<div class="tab-heading"><div><span class="eyebrow">DE LA IDEA A LA ACCIÓN</span><h2>Tablero de tareas</h2><p>Repartid el trabajo, moved las tarjetas y marcad cada avance.</p></div><button class="btn primary" data-action="new-task">${I('plus',17)} Añadir tarea</button></div><div class="kanban">${[['todo','Por hacer','clock'],['doing','En curso','activity'],['done','Hechas','checkcircle']].map(([state,label,icon])=>`<div class="kanban-col" data-drop="${state}"><div class="kanban-head"><span class="kanban-head-icon ${state}">${I(icon,18)}</span><b>${label}</b><small>${p.tasks.filter(x=>x.state===state).length}</small></div><div class="kanban-cards">${p.tasks.filter(x=>x.state===state).map(t=>`<div class="kanban-card" draggable="true" data-drag="${t.id}"><div class="task-card-top"><span class="priority ${t.priority}">${t.priority==='high'?'● Alta':t.priority==='low'?'● Baja':'● Normal'}</span><button class="icon-btn small" data-action="edit-task" data-id="${t.id}" title="Editar">${I('more',17)}</button></div><button class="kanban-title" data-action="edit-task" data-id="${t.id}">${e(t.title)}</button>${t.description?`<p>${e(t.description.slice(0,105))}</p>`:''}${checklistChip(t)}<div class="kanban-foot"><span>${t.due_date?I('calendar',14)+' '+short(t.due_date):I('clock',14)+' Sin fecha'}</span>${t.assigned_to?avatar(S.dash.users.find(u=>u.id===t.assigned_to)?.name||'?','tiny'):'<span class="tiny-unassigned">Ambos</span>'}</div></div>`).join('')||'<div class="kanban-empty">Arrastra tareas aquí</div>'}</div><button class="kanban-add" data-action="new-task" data-state="${state}">${I('plus',17)} Nueva tarea</button></div>`).join('')}</div>`;}
function checklistChip(t){const c=S.project.checklists.filter(x=>x.task_id===t.id);return c.length?`<span class="checklist-chip">${I('checkcircle',13)} ${c.filter(x=>x.done).length}/${c.length} pasos</span>`:'';}
function checklistDetail(t){const steps=S.project.checklists.filter(c=>c.task_id===t.id);return `<div class="task-steps"><div class="task-steps-title"><b>Checklist compartida</b><small>${steps.filter(x=>x.done).length}/${steps.length} terminados</small></div>${steps.length?steps.map(c=>`<div class="step-row"><button class="step-toggle ${c.done?'checked':''}" type="button" data-action="toggle-step" data-id="${c.id}" title="Completar paso">${c.done?I('check',13):''}</button><span class="${c.done?'completed':''}">${e(c.title)}</span><button type="button" class="icon-btn small" data-action="delete-step" data-id="${c.id}" title="Eliminar paso">${I('close',14)}</button></div>`).join(''):'<p class="step-empty">Dividid esta tarea en pasos manejables.</p>'}<div class="step-input"><input type="text" id="step-title" maxlength="180" placeholder="Nuevo paso de esta tarea…"/><button type="button" class="btn subtle" data-action="add-step" data-id="${t.id}">${I('plus',15)} Añadir</button></div></div>`;}
const euro=n=>Number(n||0).toLocaleString('es-ES',{style:'currency',currency:'EUR'});
const MILESTONES={planned:'Pendiente',doing:'En marcha',done:'Conseguido'};
const categories={general:'General',design:'Diseño',development:'Desarrollo',marketing:'Marketing',transport:'Transporte',stay:'Alojamiento',food:'Comidas',activities:'Actividades',other:'Otros'};
function roadmapTab(){const p=S.project,done=p.milestones.filter(m=>m.state==='done').length;return `<div class="tab-heading"><div><span class="eyebrow">DEL PRIMER PASO AL ÚLTIMO</span><h2>Hoja de ruta compartida</h2><p>Organizad fases, entregas y objetivos, tanto del proyecto profesional como del plan personal.</p></div><button class="btn primary" data-action="new-milestone">${I('plus',17)} Nuevo hito</button></div><section class="roadmap-head"><div><span class="eyebrow">VUESTRO RECORRIDO</span><h3>${done} de ${p.milestones.length} hitos alcanzados</h3></div><div class="roadmap-progress">${progressHtml(done,p.milestones.length)}</div></section><div class="roadmap-list">${p.milestones.length?p.milestones.map((m,i)=>`<article class="milestone"><div class="milestone-spine"><span class="milestone-node ${m.state}">${m.state==='done'?I('check',17):String(i+1).padStart(2,'0')}</span></div><div class="milestone-card"><div class="milestone-meta"><span class="phase-label">FASE ${String(i+1).padStart(2,'0')}</span><span class="status status-${m.state==='planned'?'idea':m.state==='doing'?'active':'done'}">${MILESTONES[m.state]}</span></div><h3>${e(m.title)}</h3>${m.description?`<p>${e(m.description)}</p>`:''}<div class="milestone-foot"><span>${I('calendar',14)} ${m.due_date?fmt(m.due_date):'Sin fecha'}</span><button class="btn subtle" data-action="edit-milestone" data-id="${m.id}">${I('edit',14)} Editar</button></div></div></article>`).join(''):`<div class="full-empty">${I('layers',34)}<h3>Todos los grandes planes empiezan por un hito.</h3><p>Definid las etapas que queréis alcanzar juntos.</p><button class="btn primary" data-action="new-milestone">Crear primer hito</button></div>`}</div>`;}
function budgetTab(){const p=S.project,est=p.expenses.reduce((v,x)=>v+x.estimated,0),real=p.expenses.reduce((v,x)=>v+x.actual,0),delta=est-real;return `<div class="tab-heading"><div><span class="eyebrow">NÚMEROS CLAROS, DECISIONES MEJORES</span><h2>Presupuesto compartido</h2><p>Presupuesto previsto y gasto real para un proyecto, viaje o cualquier plan.</p></div><button class="btn primary" data-action="new-expense">${I('plus',17)} Añadir concepto</button></div><div class="budget-stats"><section class="budget-stat"><small>PREVISTO</small><strong>${euro(est)}</strong><span>Presupuesto total</span></section><section class="budget-stat"><small>GASTADO</small><strong>${euro(real)}</strong><span>Coste registrado</span></section><section class="budget-stat ${delta<0?'over':''}"><small>${delta>=0?'MARGEN RESTANTE':'SOBREPASADO'}</small><strong>${euro(Math.abs(delta))}</strong><span>${delta>=0?'Disponible respecto a lo previsto':'Por encima de lo previsto'}</span></section></div><section class="panel budget-table-panel"><div class="panel-title"><h3>Desglose de conceptos</h3><span class="mini-label">Visible y editable para los dos</span></div><div class="budget-scroll"><table class="budget-table"><thead><tr><th>Concepto</th><th>Categoría</th><th>Previsto</th><th>Real</th><th></th></tr></thead><tbody>${p.expenses.length?p.expenses.map(x=>`<tr><td><b>${e(x.title)}</b></td><td><span class="category-tag">${categories[x.category]||'Otros'}</span></td><td>${euro(x.estimated)}</td><td>${euro(x.actual)}</td><td><button class="icon-btn" data-action="edit-expense" data-id="${x.id}" aria-label="Editar gasto">${I('edit',16)}</button></td></tr>`).join(''):`<tr><td colspan="5"><div class="empty-mini">Todavía no hay gastos. Podéis empezar con una estimación.</div></td></tr>`}</tbody></table></div></section>`;}
function notesTab(){const p=S.project;return `<div class="tab-heading"><div><span class="eyebrow">PENSAR Y CREAR JUNTOS</span><h2>Notas, ideas y diseños</h2><p>Cread secciones para investigar, estructurar, diseñar y documentar cada proyecto.</p></div><button class="btn primary" data-action="new-section">${I('plus',17)} Nueva sección</button></div><div class="notes-layout">${p.sections.length?p.sections.map((n,i)=>`<article class="section-note"><div class="note-top"><div class="note-num">${String(i+1).padStart(2,'0')}</div><div class="note-heading"><h3>${e(n.title)}</h3><small>Última edición: ${fmt(n.updated_at)} · Versión ${n.revision}</small></div><button class="btn subtle" data-action="edit-section" data-id="${n.id}">${I('edit',16)} Editar</button></div><div class="note-body">${n.content?formatNote(n.content):'<span class="muted">Esta sección está lista para añadir contenido.</span>'}</div></article>`).join(''):`<div class="full-empty">${I('file',35)}<h3>Todo empieza con una nota.</h3><p>La idea, el briefing, referencias, diseños, decisiones… organizad todo por secciones.</p><button class="btn primary" data-action="new-section">Crear primera sección</button></div>`}<button class="new-note-tile" data-action="new-section">${I('plus',22)} Añadir otra sección al proyecto</button></div>`;}
function formatNote(txt){return e(txt).split('\n').map(line=>{if(line.startsWith('### '))return `<h5>${line.slice(4)}</h5>`;if(line.startsWith('## '))return `<h4>${line.slice(3)}</h4>`;if(line.startsWith('# '))return `<h3>${line.slice(2)}</h3>`;if(/^[-*] /.test(line))return `<p class="md-li">• ${line.slice(2)}</p>`;return `<p>${line||'&nbsp;'}</p>`;}).join('').replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>');}
function projectDatesTab(){const p=S.project;return `<div class="tab-heading"><div><span class="eyebrow">TIEMPO DE CALIDAD Y OBJETIVOS</span><h2>Planes, hitos y fechas</h2><p>Desde un vuelo o una cena hasta una entrega o lanzamiento.</p></div><button class="btn primary" data-action="new-event">${I('plus',17)} Añadir fecha</button></div><div class="event-grid">${p.events.length?p.events.map(ev=>`<article class="event-card"><div class="event-day"><strong>${new Date(ev.event_date+'T12:00:00').getDate()}</strong><span>${new Date(ev.event_date+'T12:00:00').toLocaleDateString('es-ES',{month:'short'}).toUpperCase()}</span></div><div class="event-card-body"><h3>${e(ev.title)}</h3><p>${ev.location?I('pin',15)+' '+e(ev.location):'Sin lugar indicado'}</p>${ev.notes?`<small>${e(ev.notes)}</small>`:''}</div><div class="event-controls"><button class="icon-btn" data-action="edit-event" data-id="${ev.id}" title="Editar">${I('edit',16)}</button><button class="icon-btn" data-action="delete-item" data-kind="events" data-id="${ev.id}" title="Eliminar">${I('trash',16)}</button></div></article>`).join(''):`<div class="full-empty">${I('calendar',36)}<h3>Aún no hay nada en la agenda.</h3><p>Una cena especial, unas vacaciones o el día de lanzamiento de una idea.</p><button class="btn primary" data-action="new-event">Crear un plan</button></div>`}</div>`;}
function filesTab(){const p=S.project;return `<div class="tab-heading"><div><span class="eyebrow">TODO A MANO</span><h2>Archivos y referencias</h2><p>Compartid imágenes, PDFs, mockups y enlaces importantes.</p></div><div class="buttons-inline"><button class="btn outline" data-action="new-link">${I('link',17)} Añadir enlace</button><button class="btn primary" data-action="new-file">${I('upload',17)} Subir archivo</button></div></div><div class="files-two"><section class="panel"><div class="panel-title"><h3>Archivos (${p.assets.length})</h3></div>${p.assets.map(a=>`<div class="file-row"><span class="file-type">${I(a.mime.startsWith('image/')?'folder':'file',19)}</span><div><a target="_blank" rel="noopener" href="/api/assets/${a.id}">${e(a.name)}</a><small>${Math.round(a.size/1024)} KB · ${fmt(a.created_at)}</small></div><button class="icon-btn" data-action="delete-item" data-kind="assets" data-id="${a.id}" title="Eliminar">${I('trash',16)}</button></div>`).join('')||'<div class="empty-mini">No hay archivos todavía.</div>'}</section><section class="panel"><div class="panel-title"><h3>Enlaces (${p.links.length})</h3></div>${p.links.map(l=>`<div class="file-row"><span class="file-type">${I('globe',19)}</span><div><a href="${e(l.url)}" target="_blank" rel="noopener noreferrer">${e(l.label)} ↗</a><small class="ellipsis">${e(l.url)}</small></div><button class="icon-btn" data-action="delete-item" data-kind="links" data-id="${l.id}" title="Eliminar">${I('trash',16)}</button></div>`).join('')||'<div class="empty-mini">Añadid aquí vuestras referencias.</div>'}</section></div>`;}
function chatTab(){const p=S.project;return `<div class="tab-heading"><div><span class="eyebrow">VAMOS HABLANDO</span><h2>Conversación del proyecto</h2><p>Dejad propuestas, preguntas, decisiones y actualizaciones para el otro.</p></div></div><div class="chat-panel">${p.comments.length?p.comments.map(c=>`<div class="comment"><span class="avatar ${c.user_id===S.me.id?'av-first':'av-second'}">${e(initials(c.author))}</span><div><div class="comment-head"><b>${e(c.author)}</b><small>${fmt(c.created_at)} · ${new Date(c.created_at).toLocaleTimeString('es-ES',{hour:'2-digit',minute:'2-digit'})}</small></div><div class="comment-body">${e(c.content)}</div></div></div>`).join(''):`<div class="empty-mini">Todavía no hay mensajes. ¡Rompe el hielo!</div>`}<form id="comment-form" class="comment-form"><textarea name="content" rows="2" maxlength="3000" placeholder="Escribe una idea, pregunta o actualización…" required></textarea><button class="btn primary" type="submit">Enviar ${I('arrow',17)}</button></form></div>`;}
function projectActivityTab(){return `<div class="tab-heading"><div><span class="eyebrow">TODO QUEDA REGISTRADO</span><h2>Historial compartido</h2><p>Quién hizo qué, cuándo, en este proyecto.</p></div></div><section class="panel">${recentHtml(S.project.activities)}</section>`;}
function aiTab(){const active=S.dash.integrations.ai;return `<div class="ai-screen"><div class="ai-hero"><span class="ai-stamp">${I('spark',24)}</span><div><span class="eyebrow">SOLO PARA PROYECTOS DE TRABAJO</span><h2>Laboratorio de ideas con IA</h2><p>Estructura proyectos, desglosa tareas, mejora ideas y crea mockups HTML. El resultado se puede guardar como una nota del proyecto.</p></div></div><div class="ai-layout"><section class="panel"><div class="panel-title"><h3>¿En qué os ayudamos?</h3><span class="integration-badge ${active?'connected':'disconnected'}">${active?'IA configurada':'Sin clave IA'}</span></div><form id="ai-form" class="stack-form"><label>Tipo de ayuda<select name="type" id="ai-type">${[['ideas','Explorar y mejorar ideas'],['plan','Plan de desarrollo'],['tasks','Dividir en tareas'],['mockup','Generar mockup HTML'],['custom','Petición personalizada']].map(([k,v])=>`<option value="${k}" ${S.aiType===k?'selected':''}>${v}</option>`).join('')}</select></label><label>Indicaciones para la IA <span class="field-note">(opcional)</span><textarea name="prompt" rows="5" placeholder="Por ejemplo: quiero una app para gestionar campañas con un estilo minimalista…">${e(S.aiPrompt)}</textarea></label><button class="btn primary full" ${active?'':'disabled'} type="submit">${I('spark',17)} Generar con IA</button>${!active?`<p class="hint">Para activarla, el administrador debe añadir <code>OPENAI_API_KEY</code> al archivo <code>.env</code> del servidor. La clave nunca se envía al navegador.</p>`:''}</form><div class="ai-separator"><span>O IMPORTA UNA IDEA DE OTRA IA</span></div><form id="ai-import" class="stack-form"><label>Pega el texto de ChatGPT, Claude u otra herramienta<textarea name="content" rows="4" required placeholder="Pega aquí el briefing, las propuestas o las ideas que quieras incorporar al proyecto…"></textarea></label><label>Título de la nota<input name="title" placeholder="Ideas importadas de IA" maxlength="150" /></label><button class="btn outline full" type="submit">${I('plus',17)} Guardar en el proyecto</button></form></section><section class="panel ai-result-panel"><div class="panel-title"><h3>Resultado</h3>${S.aiResult?`<button class="btn subtle" data-action="save-ai">${I('file',16)} Guardar como nota</button>`:''}</div>${S.aiResult?`<div class="ai-output">${S.aiResult.type==='mockup'?`<div class="mockup-top"><span>Previsualización del mockup</span><button class="text-btn" data-action="download-mockup">${I('download',15)} Exportar HTML</button></div><iframe id="mockup-frame" sandbox="" title="Previsualización segura del mockup"></iframe><details><summary>Ver código HTML</summary><pre>${e(S.aiResult.content)}</pre></details>`:`<div class="ai-text-output">${e(S.aiResult.content)}</div>`}</div>`:`<div class="ai-placeholder"><div class="glow-spark">✳</div><h3>Vuestra próxima gran idea<br/>puede empezar aquí.</h3><p>Elegid una ayuda y generad contenido aprovechando la descripción y las notas del proyecto.</p></div>`}</section></div></div>`;}
function ideaCard(i){return `<div class="idea-card"><div class="idea-card-top"><span class="space-pill ${i.space}">${i.space==='work'?'Trabajo':'Planes en común'}</span><span class="idea-state">${{inbox:'Idea nueva',considering:'Valorando',converted:'Convertida a proyecto'}[i.state]}</span></div><h3>${e(i.title)}</h3><p>${e(i.body||'Escribid aquí cómo imagináis esta idea y sus próximos pasos.')}</p><div class="idea-actions"><button class="btn outline" data-action="edit-idea" data-id="${i.id}">${I('edit',15)} Editar</button>${i.project_id?`<button class="btn primary" data-project="${i.project_id}">Abrir proyecto ${I('arrow',15)}</button>`:`<button class="btn primary" data-action="convert-idea" data-id="${i.id}">Convertir en proyecto ${I('arrow',15)}</button>`}</div></div>`;}
function projectReportHTML(p){const tr=(arr,head,body)=>arr.length?`<section><h2>${head}</h2>${arr.map(body).join('')}</section>`:'';
 const esc=e,done=p.tasks.filter(t=>t.state==='done').length;const money=n=>Number(n||0).toLocaleString('es-ES',{style:'currency',currency:'EUR'});
 return `<!doctype html><html lang="es"><head><meta charset="utf-8"/><title>Informe · ${esc(p.title)}</title><style>@page{size:A4;margin:18mm}body{font:12px/1.55 -apple-system,BlinkMacSystemFont,'Segoe UI',Arial,sans-serif;color:#263348;margin:0}header{border-bottom:4px solid #334477;padding-bottom:25px;margin-bottom:25px}header small{letter-spacing:2px;font-size:10px;font-weight:800;color:#7181a0}h1{font-size:32px;line-height:1.2;margin:13px 0}h2{font-size:16px;border-bottom:1px solid #dbe0e8;padding-bottom:7px;margin-top:27px}p{white-space:pre-wrap}section{page-break-inside:avoid}article{margin:9px 0;padding:10px 0;border-bottom:1px solid #eef0f4}article strong{display:block}article small{display:block;color:#718097}footer{border-top:1px solid #dae1ed;padding-top:17px;margin-top:35px;color:#8590a0;font-size:10px}@media print{button{display:none}}button{padding:10px 18px;background:#334477;border:0;border-radius:9px;color:white;cursor:pointer;margin:12px 0}</style></head><body><header><small>DOS ESPACIOS · ÁLVARO + ANGIE · ${p.space==='work'?'TRABAJO':'PLANES EN COMÚN'}</small><h1>${esc(p.title)}</h1><p>${esc(p.description)}</p><div>${esc(STATUS[p.status])} · ${done}/${p.tasks.length} tareas terminadas</div></header><button onclick="window.print()">Imprimir o guardar como PDF</button>${tr(p.milestones,'Hitos',m=>`<article><strong>${esc(m.title)}</strong><small>${esc(m.state)} · ${fmt(m.due_date)}</small><p>${esc(m.description)}</p></article>`)}${tr(p.tasks,'Tareas',t=>`<article><strong>◻ ${esc(t.title)}</strong><small>${esc(t.state)} · ${fmt(t.due_date)}</small><p>${esc(t.description)}</p></article>`)}${tr(p.sections,'Documentación y notas',n=>`<article><strong>${esc(n.title)}</strong><p>${esc(n.content)}</p></article>`)}${tr(p.decisions||[],'Decisiones',d=>`<article><strong>${esc(d.title)}</strong><p>${esc(d.description)}</p><small>${d.choices.map(c=>esc(c)).join(' · ')}</small></article>`)}${tr(p.events,'Fechas y planes',ev=>`<article><strong>${esc(ev.title)}</strong><small>${fmt(ev.event_date)} · ${esc(ev.location)}</small><p>${esc(ev.notes)}</p></article>`)}${tr(p.expenses,'Presupuesto',x=>`<article><strong>${esc(x.title)}</strong><small>Previsto ${money(x.estimated)} · Real ${money(x.actual)}</small></article>`)}<footer>Documento generado desde DOS ESPACIOS el ${new Date().toLocaleDateString('es-ES')}. Los datos corresponden al momento de la exportación.</footer></body></html>`;}
function ideasPage(){const ideas=S.dash.ideas||[],open=ideas.filter(x=>x.state!=='converted'),done=ideas.filter(x=>x.state==='converted');return `<div class="page"><div class="page-heading"><span class="eyebrow">DONDE EMPIEZA TODO</span><h1>Buzón de ideas<span class="title-dot">.</span></h1><p>Un lugar para soltar ideas, desarrollarlas juntos y convertirlas en proyectos cuando os apetezca.</p></div><div class="tool-intro"><div><b>${open.length} ideas por explorar</b><small>Todo compartido entre Álvaro y Angie, desde el primer boceto.</small></div><button class="btn primary" data-action="new-idea">${I('plus',17)} Nueva idea</button></div><div class="ideas-grid">${open.length?open.map(ideaCard).join(''):'<div class="empty-mini">Todavía no habéis añadido ideas al buzón. ¿Cuál será la primera?</div>'}</div>${done.length?`<section class="panel"><div class="panel-title"><h3>Ideas convertidas en proyectos</h3></div><div class="ideas-grid compact">${done.map(ideaCard).join('')}</div></section>`:''}</div>`;}
function searchPage(){const data=S.searchResults;const allFound=data?Object.values(data.results).flat():[];return `<div class="page"><div class="page-heading"><span class="eyebrow">ENCONTRAD LO QUE IMPORTA</span><h1>Buscar en todo<span class="title-dot">.</span></h1><p>Proyectos, tareas, ideas, notas, hitos y planes desde un único lugar.</p></div><form id="search-form" class="global-search"><input name="q" minlength="2" maxlength="100" required value="${e(data?.query||'')}" placeholder="Por ejemplo: Italia, web, publicidad, restaurante…"/><button class="btn primary" type="submit">${I('search',16)} Buscar</button></form>${data?`<div class="search-summary">${allFound.length} resultados encontrados para «${e(data.query)}»</div><div class="search-results">${allFound.map(x=>`<button class="search-result" ${x.project_id?`data-project="${e(x.project_id)}"`:'data-nav="ideas"'}><span class="search-type">${{project:'Proyecto',idea:'Idea',tasks:'Tarea',notes:'Nota',milestones:'Hito',events:'Fecha'}[x.type]||'Elemento'} · ${x.space==='work'?'Trabajo':'Planes'}</span><b>${e(x.title)}</b><small>${e((x.snippet||'').slice(0,220))}</small>${I('arrow',16)}</button>`).join('')||'<div class="empty-mini">No hay coincidencias. Prueba con otros términos.</div>'}</div>`:'<div class="empty-mini">Busca algo que hayáis creado cualquiera de los dos.</div>'}</div>`;}
function notificationsPage(){const data=S.noticeData;return `<div class="page"><div class="page-heading"><span class="eyebrow">SIN PERDEROS NADA</span><h1>Notificaciones<span class="title-dot">.</span></h1><p>Los cambios de la otra persona, guardados aunque no estuvieras conectado.</p></div><div class="tool-intro"><b>${data?.unread||0} por leer</b><button class="btn outline" data-action="mark-all-read">${I('check',16)} Marcar todas como leídas</button></div><section class="panel"><div class="notice-list">${data?.items?.length?data.items.map(n=>`<div class="notice-item ${n.read_at?'':'unread'}"><div class="notice-icon">${I('bell',18)}</div><div><b>${e(n.actor_name||'El otro')} ${e(n.action)}</b><p>${e(n.detail)} ${n.project_title?'· '+e(n.project_title):''}</p><small>${fmt(n.created_at)}</small></div><div class="notice-actions">${n.project_id?`<button class="btn outline" data-project="${n.project_id}">Abrir</button>`:''}${!n.read_at?`<button class="icon-btn" data-action="read-notice" data-id="${n.id}" title="Marcar leída">${I('check',17)}</button>`:''}</div></div>`).join(''):'<div class="empty-mini">Sin notificaciones por ahora. Cualquier cambio compartido aparecerá aquí.</div>'}</div></section></div>`;}
function archivesPage(){const list=S.archiveData?.projects||[];return `<div class="page"><div class="page-heading"><span class="eyebrow">PROYECTOS GUARDADOS</span><h1>Archivados<span class="title-dot">.</span></h1><p>Estos proyectos no aparecen en los espacios, pero siguen guardados y podéis recuperarlos.</p></div><section class="panel">${list.length?list.map(x=>`<div class="trash-row"><div><b>${e(x.title)}</b><small>${x.space==='work'?'Trabajo':'Planes en común'}</small></div><button class="btn primary" data-action="restore-archive" data-id="${x.id}">${I('undo',16)} Desarchivar</button></div>`).join(''):'<div class="empty-mini">No hay proyectos archivados.</div>'}</section></div>`;}
function trashPage(){const list=S.trashData?.projects||[];return `<div class="page"><div class="page-heading"><span class="eyebrow">SEGUNDA OPORTUNIDAD</span><h1>Papelera de proyectos<span class="title-dot">.</span></h1><p>Los proyectos eliminados pueden recuperarse. La eliminación definitiva borra también los archivos.</p></div><section class="panel">${list.length?list.map(x=>`<div class="trash-row"><div><b>${e(x.title)}</b><small>${x.space==='work'?'Trabajo':'Planes en común'} · ${fmt(x.deleted_at)}</small></div><div class="buttons-inline"><button class="btn primary" data-action="restore-project" data-id="${x.id}">${I('undo',15)} Recuperar</button><button class="btn danger-light" data-action="purge-project" data-id="${x.id}">Eliminar definitivamente</button></div></div>`).join(''):'<div class="empty-mini">La papelera está vacía.</div>'}</section></div>`;}
function versionsPanel(){if(!S.historyData)return '';const list=S.historyData.versions||[];return `<div class="versions-panel"><div class="eyebrow">HISTORIAL DE LA NOTA</div><h3>Versiones anteriores</h3>${list.length?list.map(v=>`<div class="version-row"><div><b>Versión ${v.revision} · ${e(v.title)}</b><small>${e(v.author||'Usuario')} · ${fmt(v.created_at)}</small><p>${e(v.content.slice(0,160))}${v.content.length>160?'…':''}</p></div><button type="button" class="btn outline" data-action="restore-version" data-id="${v.id}" data-section="${v.section_id}">Recuperar</button></div>`).join(''):'<p class="hint">Esta nota todavía no tiene versiones anteriores guardadas.</p>'}</div>`;}
function decisionsTab(){const p=S.project;return `<div class="tab-heading"><div><span class="eyebrow">ELEGIMOS ENTRE LOS DOS</span><h2>Decisiones compartidas</h2><p>Plantead alternativas, votad y dejad constancia del resultado. Cada uno tiene un voto modificable hasta cerrar la decisión.</p></div><button class="btn primary" data-action="new-decision">${I('plus',17)} Nueva decisión</button></div><div class="decision-grid">${p.decisions?.length?p.decisions.map(d=>{const votes=d.votes||[],mine=votes.find(v=>v.user_id===S.me.id);return `<section class="panel decision-card"><div class="idea-card-top"><span class="space-pill ${p.space}">${p.space==='work'?'Trabajo':'Planes en común'}</span><span class="idea-state">${d.closed?'Cerrada':'Abierta'}</span></div><h3>${e(d.title)}</h3><p>${e(d.description||'Elegid una de las opciones propuestas.')}</p><div class="decision-choices">${d.choices.map((option,i)=>{const total=votes.filter(v=>v.choice_index===i).length;return `<button class="decision-choice ${mine?.choice_index===i?'selected':''}" data-action="vote-decision" data-id="${d.id}" data-choice="${i}" ${d.closed?'disabled':''}><span>${e(option)}</span><strong>${total} ${total===1?'voto':'votos'} ${mine?.choice_index===i?'✓':''}</strong></button>`}).join('')}</div><div class="decision-foot"><small>${votes.length}/2 personas han votado</small><div class="buttons-inline"><button class="btn outline" data-action="close-decision" data-id="${d.id}" data-closed="${d.closed?0:1}">${d.closed?'Reabrir':'Cerrar votación'}</button><button class="icon-btn" data-action="delete-decision" data-id="${d.id}" title="Eliminar decisión">${I('trash',16)}</button></div></div></section>`}).join(''):'<div class="empty-mini">Todavía no hay decisiones registradas. Probad a elegir un destino, una propuesta o el diseño de una campaña.</div>'}</div>`;}
function knowledgePage(){const list=S.knowledgeData?.entries||[];return `<div class="page"><div class="page-heading"><span class="eyebrow">INFORMACIÓN REUTILIZABLE</span><h1>Biblioteca de conocimiento<span class="title-dot">.</span></h1><p>Preguntas, respuestas, decisiones e investigaciones que queréis conservar. Todo es compartido; nada se envía automáticamente a IA externa.</p></div><div class="tool-intro"><div><b>${list.length} aprendizajes documentados</b><small>Conservad contexto, fuentes y qué conocimientos están realmente validados.</small></div><button class="btn primary" data-action="new-knowledge">${I('plus',16)} Añadir conocimiento</button></div><div class="ideas-grid">${list.length?list.map(k=>`<article class="idea-card"><div class="idea-card-top"><span class="space-pill ${k.space}">${k.space==='work'?'Trabajo':'Planes en común'}</span><span class="idea-state">${{draft:'Por revisar',reviewed:'Revisado',validated:'Validado'}[k.status]}</span></div><h3>${e(k.title)}</h3><p><b>Pregunta:</b> ${e(k.question||'Sin pregunta')}<br><b>Respuesta:</b> ${e(k.answer||'Pendiente de responder')}</p><small>${e(k.source?'Fuente: '+k.source:'Sin fuente documentada')} · ${e(k.author||'Usuario')}</small><div class="idea-actions"><button class="btn outline" data-action="edit-knowledge" data-id="${k.id}">Editar</button>${k.project_id?`<button class="btn outline" data-project="${k.project_id}">Proyecto</button>`:''}</div></article>`).join(''):'<div class="empty-mini">Todavía no hay conocimientos. Registrad la primera pregunta y añadid su respuesta cuando esté contrastada.</div>'}</div></div>`;}
function intelligencePage(){const d=S.analyticsData;if(!d)return `<div class="page"><p>Cargando indicadores…</p></div>`;const t=d.totals||{};const trend=d.trend||[],max=Math.max(1,...trend.map(x=>x.changes));return `<div class="page"><div class="page-heading"><span class="eyebrow">DATOS VERIFICABLES · HISTORIAL</span><h1>Datos e inteligencia<span class="title-dot">.</span></h1><p>Métricas calculadas con vuestras tablas reales. Las actividades históricas anteriores a este módulo no se reconstruyen artificialmente.</p></div><div class="intel-filters">${[['all','Ambos espacios'],['work','Trabajo'],['couple','Planes en común']].map(([key,label])=>`<button class="btn ${S.analyticsSpace===key?'primary':'outline'}" data-action="filter-analytics" data-space="${key}">${label}</button>`).join('')}</div><div class="stat-grid">${kpi('folder','Proyectos',t.projects??0,'Sin eliminados')}${kpi('checkcircle','Tareas finalizadas',t.done??0,`De ${t.tasks||0} tareas`)}${kpi('inbox','Ideas',t.ideas??0,'Registradas')}${kpi('file','Conocimientos',t.knowledge??0,'Documentados')}</div><section class="panel"><div class="panel-title"><h3>Registro de actividad</h3></div><p class="hint">Cambios registrados desde esta ampliación. No mide las visitas ni recoge datos fuera de la aplicación.</p><div class="intel-bars">${trend.length?trend.map(x=>`<div class="intel-bar-col" title="${e(x.date)}: ${x.changes} cambios"><div class="intel-bar" style="height:${Math.max(5,Math.round(x.changes/max*115))}px"></div><small>${e(x.date.slice(5))}</small></div>`).join(''):'<div class="empty-mini">No hay cambios registrados todavía.</div>'}</div></section><div class="tool-intro"><div><b>Biblioteca de aprendizajes</b><small>Las conclusiones validadas pueden reutilizarse en futuros proyectos.</small></div><button class="btn primary" data-nav="knowledge">Abrir conocimiento ${I('arrow',16)}</button></div><p class="hint">Origen: ${e(d.source)} · Actualizado: ${fmt(d.updated_at)}</p></div>`;}
function guardianPage(){const d=S.guardianData;return `<div class="page"><div class="page-heading"><span class="eyebrow">CALIDAD, RIESGOS Y EVIDENCIA</span><h1>Director General<span class="title-dot">.</span></h1><p>Revisión técnica basada en pruebas ejecutadas. Este panel no lanza comandos en el servidor web ni autoriza publicaciones automáticamente.</p></div>${d?.available?`<div class="tool-intro"><div><b>Última evaluación: ${e(d.release_decision)}</b><small>${fmt(d.generated_at)} · ${e(d.project)}</small></div><span class="idea-state" style="color:white">${(d.tests||[]).filter(t=>t.passed).length}/${d.tests.length} pruebas pasan</span></div><div class="stat-grid">${kpi('alert','Alertas altas',d.counts?.high||0,'Revisión necesaria')}${kpi('activity','Alertas medias',d.counts?.medium||0,'Hipótesis a validar')}</div><section class="panel"><div class="panel-title"><h3>Incidencias</h3></div>${d.findings.length?d.findings.map(f=>`<div class="version-row"><div><b>${e(f.title)} · ${e(f.severity)}</b><p>${e(f.why)}</p><small>Acción sugerida: ${e(f.remediation)}</small></div></div>`).join(''):'<p>No hay hallazgos con las reglas estáticas actuales. No significa que no existan vulnerabilidades.</p>'}</section>`:`<div class="tool-intro"><div><b>Sin auditoría reciente publicada en el panel</b><small>${e(d?.reason||'Ejecuta npm run guardian:private en un entorno de administración.')}</small></div></div>`}<section class="panel"><div class="panel-title"><h3>Principios de supervisión</h3></div><p>El supervisor compara código, pruebas y controles definidos. Para hacer cambios requiere un entorno autorizado. Las revisiones no sustituyen pentests independientes ni revisión legal.</p></section></div>`;}
function datesPage(){const dates=S.dash.upcoming.sort((a,b)=>a.date.localeCompare(b.date));return `<div class="page"><div class="page-heading"><span class="eyebrow">VUESTROS MOMENTOS IMPORTANTES</span><h1>Fechas y planes<span class="title-dot">.</span></h1><p>Todo lo que se acerca en vuestros dos espacios.</p></div><div class="dates-view">${dates.length?dates.map(x=>`<div class="date-list-line">${upcomingLine(x)}<span class="kind-badge">${x.kind==='task'?'Tarea':'Plan'}</span></div>`).join(''):'<div class="full-empty">No hay fechas todavía. Podéis añadirlas desde cualquier proyecto.</div>'}</div><div class="calendar-export"><div>${I('calendar',26)}<div><b>Llevadlo a vuestro calendario</b><small>Descargad un archivo .ics compatible con calendarios habituales. La importación es manual, no sincronización bidireccional.</small></div></div><a class="btn outline" href="/api/calendar.ics">${I('download',16)} Exportar calendario</a></div></div>`;}
function activityPage(){return `<div class="page"><div class="page-heading"><span class="eyebrow">CADA PASO CUENTA</span><h1>La actividad de los dos<span class="title-dot">.</span></h1><p>Todos los cambios quedan anotados para que sepáis quién ha hecho qué.</p></div><div class="panel activity-big">${recentHtml(S.dash.recent)}</div></div>`;}
function connectionsPage(){return `<div class="page"><div class="page-heading"><span class="eyebrow">IDEAS CONECTADAS</span><h1>Conexiones e IA<span class="title-dot">.</span></h1><p>Solo el espacio de Trabajo puede enviar contenido a servicios externos de IA o automatización.</p></div><div class="connection-grid"><section class="panel connection-card"><div class="connection-head"><span class="connection-icon">${I('spark',25)}</span><span class="integration-badge ${S.dash.integrations.ai?'connected':'disconnected'}">${S.dash.integrations.ai?'Configurado':'Por conectar'}</span></div><h3>Asistente con IA</h3><p>Ideas, planes, listas de tareas y mockups HTML a partir del contenido de cada proyecto profesional.</p><small>Modelo configurado: ${e(S.dash.integrations.model)}</small></section><section class="panel connection-card"><div class="connection-head"><span class="connection-icon">${I('layers',25)}</span><span class="integration-badge ${S.dash.integrations.webhook?'connected':'disconnected'}">${S.dash.integrations.webhook?'Configurado':'Por conectar'}</span></div><h3>n8n / Make / Webhooks</h3><p>Al cambiar un proyecto de Trabajo, se puede enviar una notificación para activar una automatización externa.</p><small>La URL se configura exclusivamente en el servidor.</small></section><section class="panel connection-card"><div class="connection-head"><span class="connection-icon">${I('link',25)}</span><span class="integration-badge connected">Disponible</span></div><h3>Figma, Canva y otros enlaces</h3><p>Adjuntad enlaces a mockups, documentación, prototipos, diseños y repositorios dentro de cada proyecto.</p><small>Enlaces compartidos, sin conexión API automática.</small></section><section class="panel connection-card"><div class="connection-head"><span class="connection-icon">${I('upload',25)}</span><span class="integration-badge connected">Disponible</span></div><h3>Importar ideas de otras IA</h3><p>Pegad contenido generado por otros asistentes y guardadlo directamente en las notas de vuestros proyectos.</p><small>Disponible en el laboratorio de cada proyecto de Trabajo.</small></section></div><div class="safety-banner">${I('heart',21)} <span><b>Vuestro espacio de Planes en común es independiente.</b> Ningún contenido personal se manda a los proveedores IA ni al webhook profesional desde esta aplicación.</span></div></div>`;}
function settingsPage(){return `<div class="page"><div class="page-heading"><span class="eyebrow">TODO BAJO CONTROL</span><h1>Ajustes del espacio<span class="title-dot">.</span></h1><p>Vuestra información pertenece a los dos.</p></div><div class="settings-grid"><section class="panel"><div class="panel-title"><h3>Personas con acceso</h3></div>${S.dash.users.map((u,i)=>`<div class="member-line">${avatar(u.name,i===0?'av-first':'av-second')}<div><b>${e(u.name)}</b><small>${e(u.email)}</small></div><span class="member-access">Acceso completo</span></div>`).join('')}<p class="hint">La aplicación no permite registro público ni agregar una tercera cuenta.</p></section><section class="panel"><div class="panel-title"><h3>Privacidad y seguridad</h3></div><p>Los datos se almacenan en vuestro servidor y ambos podéis modificarlos. Las cuentas están protegidas mediante contraseña y sesión privada.</p><button class="btn outline" data-action="password">${I('settings',16)} Cambiar mi contraseña</button></section><section class="panel"><div class="panel-title"><h3>Copias y exportaciones</h3></div><p>Descargad una copia JSON de proyectos, tareas, comentarios, notas y fechas. Incluye los metadatos de archivos, no sus bytes.</p><a class="btn primary" href="/api/export" download="dos-espacios.json">${I('download',16)} Exportar todo</a></section><section class="panel"><div class="panel-title"><h3>Archivados</h3></div><p>Proyectos que habéis archivado y podéis volver a activar.</p><button class="btn outline" data-action="open-archives">${I('undo',16)} Ver archivados</button></section><section class="panel"><div class="panel-title"><h3>Papelera</h3></div><p>Recuperad proyectos eliminados por error. La eliminación permanente solo se realiza desde la papelera.</p><button class="btn outline" data-action="open-trash">${I('undo',16)} Abrir papelera</button></section><section class="panel"><div class="panel-title"><h3>Calendario</h3></div><p>Exportad hitos y tareas con fecha para importarlos en Apple Calendar, Google Calendar u otra aplicación.</p><a class="btn outline" href="/api/calendar.ics">${I('calendar',16)} Descargar .ics</a></section></div></div>`;}

// Formularios y modales. Todos los elementos son compartidos por los dos usuarios.
const templates={work:[['blank','Desde cero'],['website','Proyecto web y lanzamiento'],['campaign','Campaña de marketing'],['app','Aplicación o producto digital']],couple:[['blank','Desde cero'],['trip','Viaje y escapada'],['dinner','Cena o plan especial'],['shared','Proyecto o idea conjunta']]};
const statuses=Object.entries(STATUS), priorities=[['low','Baja'],['normal','Normal'],['high','Alta']],states=[['todo','Por hacer'],['doing','En curso'],['done','Hecha']],colors=[['indigo','Índigo'],['rose','Rosa'],['emerald','Verde'],['amber','Ámbar'],['sky','Azul'],['violet','Violeta']];
const options=(items,current,placeholder='')=>(placeholder?`<option value="">${e(placeholder)}</option>`:'')+items.map(([v,k])=>`<option value="${e(v)}" ${String(v)===String(current)?'selected':''}>${e(k)}</option>`).join('');
const fld=(label,name,value='',type='text',extra='')=>`<label>${label}<input name="${name}" type="${type}" value="${e(value)}" ${extra} /></label>`;
const area=(label,name,value='',rows=4,extra='')=>`<label>${label}<textarea name="${name}" rows="${rows}" ${extra}>${e(value)}</textarea></label>`;
const sel=(label,name,items,value,placeholder='')=>`<label>${label}<select name="${name}">${options(items,value,placeholder)}</select></label>`;
function modalHTML(){const m=S.modal,p=S.project;let title='',subtitle='',body='',button='Guardar cambios',danger='';
 switch(m.type){
 case 'new-decision':title='Decidir entre los dos';subtitle='Cada uno podrá votar por una alternativa.';button='Crear votación';body=`${fld('¿Qué tenemos que decidir?','title','','text','required maxlength="180" placeholder="Ej.: ¿Qué diseño elegimos?"')}${area('Contexto','description','',3,'maxlength="2000"')}${area('Opciones, una por línea (2–7)','choices','',6,'required placeholder="Opción A\nOpción B\nOpción C"')}`;break;
 case 'new-knowledge':title='Registrar un conocimiento';subtitle='Añade preguntas, respuestas, fuentes y estado de validación.';body=`${fld('Título','title','','text','required maxlength="180"')}${sel('Espacio','space',[['work','Trabajo'],['couple','Planes en común']],'work')}${area('Pregunta o problema','question','',3,'maxlength="5000"')}${area('Respuesta, solución o aprendizaje','answer','',7,'maxlength="12000"')}${fld('Fuente o referencia','source','','text','maxlength="700"')}${fld('Etiquetas','tags','','text','maxlength="350"')}${sel('Validación','status',[['draft','Por revisar'],['reviewed','Revisado'],['validated','Validado']],'draft')}`;button='Guardar conocimiento';break;
 case 'edit-knowledge':{const k=S.knowledgeData.entries.find(x=>x.id===m.id);if(!k)return '';title='Editar conocimiento';body=`${fld('Título','title',k.title,'text','required maxlength="180"')}${area('Pregunta','question',k.question,3,'maxlength="5000"')}${area('Respuesta','answer',k.answer,7,'maxlength="12000"')}${fld('Fuente','source',k.source,'text','maxlength="700"')}${fld('Etiquetas','tags',k.tags,'text','maxlength="350"')}${sel('Validación','status',[['draft','Por revisar'],['reviewed','Revisado'],['validated','Validado']],k.status)}`;danger=`<button type="button" class="btn danger-light" data-action="delete-knowledge" data-id="${k.id}">Eliminar</button>`;break;}
 case 'new-idea':title='Capturar una idea ✦';subtitle='Quedará guardada para los dos, aunque todavía no sea un proyecto.';button='Guardar idea';body=`${fld('¿Qué se os ha ocurrido?','title','','text','maxlength="160" required placeholder="Una idea con posibilidades…"')}${sel('Espacio','space',[['work','Trabajo'],['couple','Planes en común']],m.space||'work')}${area('Descripción, inspiración o primeros pasos','body','',7,'maxlength="6000" placeholder="Podéis ampliar esta idea cuando queráis."')}`;break;
 case 'edit-idea':{const i=S.dash.ideas.find(x=>x.id===m.id);if(!i)return '';title='Editar idea';subtitle='Cualquier cambio se compartirá con la otra persona.';body=`${fld('Título','title',i.title,'text','maxlength="160" required')}${area('Desarrollo de la idea','body',i.body,8,'maxlength="6000"')}${sel('Estado','state',[['inbox','Nueva'],['considering','Valorando'],['converted','Convertida']],i.state)}`;danger=`<button class="btn danger-light" data-action="delete-idea" data-id="${i.id}" type="button">${I('trash',15)} Eliminar idea</button>`;break;}
 case 'new-project':title='Una idea nueva ✦';subtitle='Un proyecto nuevo para construir entre los dos.';button='Crear proyecto';body=`${fld('Nombre del proyecto','title','','text','maxlength="120" placeholder="¿Qué vamos a crear?" required')}${sel('¿En qué espacio?','space',[['work','Trabajo (los dos)'],['couple','Planes en común (los dos)']],m.space||'work')}${sel('Estructura para empezar','template',templates[m.space||'work'],'blank')}${area('Descripción / idea inicial','description','',4,'maxlength="2500" placeholder="Contad cuál es vuestra idea y para qué sirve…"')}${sel('Estado inicial','status',statuses,'idea')}${sel('Color de la tarjeta','color',colors,m.space==='couple'?'rose':'indigo')}`;break;
 case 'edit-project':title='Editar proyecto';subtitle='Los cambios serán visibles para ambos.';body=`${fld('Nombre del proyecto','title',p.title,'text','maxlength="120" required')}${area('Descripción','description',p.description,5,'maxlength="2500"')}${sel('Estado actual','status',statuses,p.status)}${sel('Color','color',colors,p.color)}<label class="checklabel"><input type="checkbox" name="archived" ${p.archived?'checked':''}/> Archivar proyecto (no aparecerá en la lista)</label>`;danger=`<button class="btn danger-light" type="button" data-action="delete-project">${I('trash',16)} Eliminar proyecto</button>`;break;
 case 'new-task':title='Nueva tarea';subtitle='Todo lo que asignéis y editéis se compartirá.';button='Añadir tarea';body=`${fld('¿Qué hay que hacer?','title','','text','maxlength="220" required placeholder="Escribe la tarea"')}${area('Descripción','description','',3,'maxlength="5000"')}${sel('Columna','state',states,m.state||'todo')}${sel('Responsable','assigned_to',S.dash.users.map(x=>[x.id,x.name]),'','Los dos / sin asignar')}<div class="form-two">${sel('Prioridad','priority',priorities,'normal')}${fld('Fecha límite','due_date','','date')}</div>`;break;
 case 'edit-task':{const t=p.tasks.find(x=>x.id===m.id);if(!t)return '';title='Editar tarea';subtitle='Los cambios se registran en el historial.';body=`${fld('Título','title',t.title,'text','maxlength="220" required')}${area('Descripción','description',t.description,3,'maxlength="5000"')}${sel('Estado','state',states,t.state)}${sel('Responsable','assigned_to',S.dash.users.map(x=>[x.id,x.name]),t.assigned_to,'Los dos / sin asignar')}<div class="form-two">${sel('Prioridad','priority',priorities,t.priority)}${fld('Fecha límite','due_date',t.due_date||'','date')}</div>${checklistDetail(t)}`;danger=`<button class="btn danger-light" type="button" data-action="delete-item" data-kind="tasks" data-id="${t.id}">${I('trash',16)} Eliminar tarea</button>`;break;}
 case 'new-section':title='Nueva sección';subtitle='Una página para desarrollar la idea a fondo.';button='Crear sección';body=`${fld('Título de la sección','title','','text','maxlength="150" required placeholder="Ej.: Briefing, Estructura, Diseño…"')}${area('Contenido','content','',10,'maxlength="40000" placeholder="# Título\n\n- Primera idea\n- Segunda idea"')}`;break;
 case 'edit-section':{const n=p.sections.find(x=>x.id===m.id);if(!n)return '';title='Editar nota compartida';subtitle='Los cambios aparecen tras guardar. Si el otro modifica esta misma nota se detecta el conflicto.';body=`${fld('Título','title',n.title,'text','maxlength="150" required')}${area('Contenido','content',n.content,14,'maxlength="40000"')}<div class="note-form-hint">Títulos: #, ##, ###. Listas: -. Negrita: **texto**. Versión ${n.revision}.</div><button type="button" class="btn outline" data-action="note-versions" data-id="${n.id}">${I('undo',15)} Historial y restauración</button>${S.historyData?.sectionId===n.id?versionsPanel():''}`;danger=`<button class="btn danger-light" type="button" data-action="delete-item" data-kind="sections" data-id="${n.id}">${I('trash',16)} Eliminar sección</button>`;break;}
 case 'new-milestone':title='Nuevo hito';subtitle='Un objetivo importante para este proyecto compartido.';button='Añadir hito';body=`${fld('Nombre del hito','title','','text','maxlength="180" required placeholder="Ej.: Diseño aprobado, reservar el hotel…"')}${area('Qué incluye','description','',4,'maxlength="3000"')}${sel('Estado','state',[['planned','Pendiente'],['doing','En marcha'],['done','Conseguido']],'planned')}${fld('Fecha objetivo','due_date','','date')}`;break;
 case 'edit-milestone':{const item=p.milestones.find(x=>x.id===m.id);if(!item)return '';title='Editar hito';body=`${fld('Nombre','title',item.title,'text','maxlength="180" required')}${area('Descripción','description',item.description,4,'maxlength="3000"')}${sel('Estado','state',[['planned','Pendiente'],['doing','En marcha'],['done','Conseguido']],item.state)}${fld('Fecha objetivo','due_date',item.due_date||'','date')}`;danger=`<button class="btn danger-light" type="button" data-action="delete-item" data-kind="milestones" data-id="${item.id}">${I('trash',16)} Eliminar hito</button>`;break;}
 case 'new-expense':title='Nuevo concepto';subtitle='Una partida del presupuesto que ambos podéis modificar.';button='Añadir importe';body=`${fld('Concepto','title','','text','maxlength="160" required placeholder="Ej.: Diseño, hotel, anuncios…"')}${sel('Categoría','category',Object.entries(categories),'general')}<div class="form-two">${fld('Previsto (€)','estimated','0','number','min="0" max="100000000" step="0.01" required')}${fld('Real (€)','actual','0','number','min="0" max="100000000" step="0.01" required')}</div>`;break;
 case 'edit-expense':{const x=p.expenses.find(x=>x.id===m.id);if(!x)return '';title='Editar concepto';body=`${fld('Concepto','title',x.title,'text','maxlength="160" required')}${sel('Categoría','category',Object.entries(categories),x.category)}<div class="form-two">${fld('Previsto (€)','estimated',x.estimated,'number','min="0" step="0.01" required')}${fld('Real (€)','actual',x.actual,'number','min="0" step="0.01" required')}</div>`;danger=`<button class="btn danger-light" type="button" data-action="delete-item" data-kind="expenses" data-id="${x.id}">${I('trash',16)} Eliminar gasto</button>`;break;}
 case 'new-event':title='Nuevo plan o fecha';subtitle='Una fecha importante para vuestro proyecto.';button='Añadir fecha';body=`${fld('Nombre del plan','title','','text','maxlength="160" required placeholder="Cena, vuelo, entrega…"')}${fld('Día','event_date','','date','required')}${fld('Lugar (opcional)','location','','text','maxlength="220"')}${area('Detalles / recordatorio','notes','',3,'maxlength="5000"')}`;break;
 case 'edit-event':{const x=p.events.find(x=>x.id===m.id);if(!x)return '';title='Editar plan o fecha';body=`${fld('Nombre','title',x.title,'text','maxlength="160" required')}${fld('Día','event_date',x.event_date,'date','required')}${fld('Lugar','location',x.location,'text','maxlength="220"')}${area('Detalles','notes',x.notes,3,'maxlength="5000"')}`;break;}
 case 'new-link':title='Compartir enlace';subtitle='Para mockups, diseños, repositorios y referencias.';button='Añadir enlace';body=`${fld('Nombre','label','','text','maxlength="120" required placeholder="Ej.: Prototipo en Figma"')}${fld('Dirección web','url','','url','required placeholder="https://…"')}`;break;
 case 'new-file':title='Subir archivo';subtitle='Fotos, PDFs, texto o documentación. Máximo 6 MB.';button='Compartir archivo';body=`<label>Selecciona un archivo<input name="file" type="file" accept="image/png,image/jpeg,image/webp,image/gif,application/pdf,text/plain,text/markdown,.md" required /></label><div class="note-form-hint">Se guarda en el servidor privado para que ambos podáis descargarlo.</div>`;break;
 case 'password':title='Cambiar contraseña';subtitle='Solo la contraseña de tu cuenta.';button='Actualizar contraseña';body=`${fld('Contraseña actual','current','','password','required autocomplete="current-password"')}${fld('Nueva contraseña (mínimo 12 caracteres)','next','','password','required minlength="12" autocomplete="new-password"')}`;break;
 default:return '';
 }
 return `<div class="modal-overlay" data-action="close-modal"><div class="modal-card" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-head"><div><span class="eyebrow">DOS ESPACIOS</span><h2 id="modal-title">${title}</h2><p>${subtitle}</p></div><button class="icon-btn" data-action="close-modal" aria-label="Cerrar">${I('close',21)}</button></div><form class="modal-form" id="modal-form"><div class="form-fields">${body}</div><div class="modal-actions">${danger}<div class="modal-spacer"></div><button class="btn outline" type="button" data-action="close-modal">Cancelar</button><button class="btn primary" type="submit">${I('check',17)} ${button}</button></div></form></div></div>`;
}
function showModal(type,extra={}){S.historyData=null;S.modal={type,...extra};$('#modal-root').innerHTML=modalHTML();$('#modal-root .modal-card input:not([type=checkbox]):not([type=file])')?.focus();}
function closeModal(){S.historyData=null;S.modal=null;$('#modal-root').innerHTML='';if(S.pending)syncNow();}
async function saveModal(form){const m=S.modal,p=S.project;const data=Object.fromEntries(new FormData(form).entries());let id=p?.id;
 const submit=form.querySelector('[type=submit]');submit.disabled=true;
 try{
  switch(m.type){
   case 'new-decision':{const choices=String(data.choices||'').split('\n').map(x=>x.trim()).filter(Boolean);await api(`/api/projects/${id}/decisions`,'POST',{...data,choices});break;}
   case 'new-knowledge':await api('/api/knowledge','POST',data);id=null;break;
   case 'edit-knowledge':await api('/api/knowledge/'+m.id,'PATCH',{...data,revision:S.knowledgeData.entries.find(x=>x.id===m.id).revision});id=null;break;
   case 'new-idea':await api('/api/ideas','POST',data);id=null;break;
   case 'edit-idea':await api('/api/ideas/'+m.id,'PATCH',{...data,revision:S.dash.ideas.find(x=>x.id===m.id).revision});id=null;break;
   case 'new-project':{const v=await api('/api/projects','POST',data);S.modal=null;await loadDash();await openProject(v.project.id);toast('Nuevo proyecto creado y compartido.');return;}
   case 'edit-project':await api('/api/projects/'+id,'PATCH',{...data,revision:p.revision,archived:form.querySelector('[name=archived]').checked});break;
   case 'new-task':await api(`/api/projects/${id}/tasks`,'POST',data);break;
   case 'edit-task':await api(`/api/tasks/${m.id}`,'PATCH',{...data,revision:p.tasks.find(x=>x.id===m.id).revision});break;
   case 'new-section':await api(`/api/projects/${id}/sections`,'POST',data);break;
   case 'edit-section':{const n=p.sections.find(x=>x.id===m.id);await api(`/api/sections/${m.id}`,'PATCH',{...data,revision:n.revision});break;}
   case 'new-milestone':await api(`/api/projects/${id}/milestones`,'POST',data);break;
   case 'edit-milestone':await api(`/api/milestones/${m.id}`,'PATCH',{...data,revision:p.milestones.find(x=>x.id===m.id).revision});break;
   case 'new-expense':await api(`/api/projects/${id}/expenses`,'POST',data);break;
   case 'edit-expense':await api(`/api/expenses/${m.id}`,'PATCH',{...data,revision:p.expenses.find(x=>x.id===m.id).revision});break;
   case 'new-event':await api(`/api/projects/${id}/events`,'POST',data);break;
   case 'edit-event':await api(`/api/events/${m.id}`,'PATCH',data);break;
   case 'new-link':await api(`/api/projects/${id}/links`,'POST',data);break;
   case 'new-file':{
    const f=form.querySelector('[type=file]').files[0];if(!f)throw Error('Selecciona un archivo');if(f.size>6*1024*1024)throw Error('El archivo supera 6 MB');
    const mime=['image/png','image/jpeg','image/webp','image/gif','application/pdf','text/plain','text/markdown'].includes(f.type)?f.type:'application/octet-stream';
    const base64=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',').pop());reader.onerror=reject;reader.readAsDataURL(f);});
    await api(`/api/projects/${id}/assets`,'POST',{name:f.name,mime,base64});break;
   }
   case 'password':await api('/api/password','POST',data);id=null;break;
  }
  S.modal=null;S.pending=false;await updateAfter(id);toast('Cambios guardados y compartidos.');
 }catch(ex){toast(ex.message,'error');if(ex.status===409){const notice=document.createElement('p');notice.className='form-error conflict';notice.textContent='Edición simultánea: copia lo que has escrito antes de cerrar. No se sobrescribirá la versión de la otra persona.';form.querySelector('.form-fields').append(notice);}}
 finally{if(submit.isConnected)submit.disabled=false;}
}
async function syncNow(){if(!S.me)return;S.pending=false;await updateAfter(S.project?.id);toast('Actualizado con los últimos cambios.','info');}
function cleanHtml(s){return String(s).replace(/^\s*```(?:html)?\s*/i,'').replace(/\s*```\s*$/,'');}
async function handleAction(el,ev){const action=el.dataset.action,id=el.dataset.id,p=S.project;
 try{
  switch(action){
   case 'toggle-menu':$('#sidebar')?.classList.toggle('mobile-open');break;
   case 'sync':await syncNow();break;
   case 'print-project':{const win=window.open('','_blank');if(!win){toast('Activa las ventanas emergentes para exportar el informe.','error');break;}win.document.open();win.document.write(projectReportHTML(p));win.document.close();win.focus();break;}
   case 'new-decision':showModal('new-decision');break;
   case 'vote-decision':await api('/api/decisions/'+id+'/vote','POST',{choice_index:Number(el.dataset.choice)});await updateAfter(p.id);toast('Voto guardado para los dos.');break;
   case 'close-decision':await api('/api/decisions/'+id+'/close','POST',{closed:el.dataset.closed==='1'});await updateAfter(p.id);toast('Votación actualizada.');break;
   case 'delete-decision':if(window.confirm('¿Eliminar esta decisión y sus votos?')){await api('/api/decisions/'+id,'DELETE');await updateAfter(p.id);toast('Decisión eliminada.');}break;
   case 'new-knowledge':showModal('new-knowledge');break;
   case 'edit-knowledge':showModal('edit-knowledge',{id});break;
   case 'delete-knowledge':if(window.confirm('¿Eliminar este conocimiento para ambos?')){await api('/api/knowledge/'+id,'DELETE');closeModal();await updateAfter(null);toast('Conocimiento eliminado');}break;
   case 'filter-analytics':S.analyticsSpace=el.dataset.space;S.analyticsData=await api('/api/analytics?space='+encodeURIComponent(S.analyticsSpace==='all'?'':S.analyticsSpace));render();break;
   case 'new-idea':showModal('new-idea');break;
   case 'edit-idea':showModal('edit-idea',{id});break;
   case 'convert-idea':{if(!window.confirm('¿Convertir esta idea en un proyecto compartido?'))break;const r=await api('/api/ideas/'+id+'/convert','POST',{});await loadDash();await openProject(r.project.id);toast('Idea convertida en proyecto.');break;}
   case 'delete-idea':{if(!window.confirm('¿Eliminar esta idea del buzón de los dos?'))break;await api('/api/ideas/'+id,'DELETE');S.modal=null;await updateAfter(null);toast('Idea eliminada.');break;}
   case 'open-archives':S.archiveData=await api('/api/archives');nav('archives');break;
   case 'restore-archive':await api('/api/archives/'+id+'/restore','POST',{});S.archiveData=await api('/api/archives');await loadDash();render();toast('Proyecto desarchivado.');break;
   case 'open-trash':S.trashData=await api('/api/trash');nav('trash');break;
   case 'restore-project':await api('/api/trash/'+id+'/restore','POST',{});S.trashData=await api('/api/trash');await loadDash();render();toast('Proyecto recuperado para los dos.');break;
   case 'purge-project':if(window.confirm('¿Eliminar DEFINITIVAMENTE este proyecto y sus archivos? No se podrá recuperar.')){await api('/api/trash/'+id+'/purge','POST',{});S.trashData=await api('/api/trash');await loadDash();render();toast('Proyecto eliminado definitivamente.');}break;
   case 'mark-all-read':await api('/api/notifications/read','POST',{});S.noticeData=await api('/api/notifications');await loadDash();render();break;
   case 'read-notice':await api('/api/notifications/read','POST',{id});S.noticeData=await api('/api/notifications');await loadDash();render();break;
   case 'note-versions':{S.historyData={sectionId:id,...await api('/api/sections/'+id+'/versions')};$('#modal-root').innerHTML=modalHTML();break;}
   case 'restore-version':{const sec=p.sections.find(x=>x.id===el.dataset.section);if(!sec)throw Error('No se encontró la nota');if(!window.confirm('¿Recuperar esta versión anterior? La versión actual quedará guardada en el historial.'))break;await api('/api/sections/'+sec.id+'/versions/'+id+'/restore','POST',{revision:sec.revision});S.historyData=null;S.modal=null;await updateAfter(p.id);toast('Versión recuperada con éxito.');break;}
   case 'new-project':showModal('new-project',{space:el.dataset.space||(['work','couple'].includes(S.view)?S.view:'work')});break;
   case 'edit-project':showModal('edit-project');break;
   case 'new-task':showModal('new-task',{state:el.dataset.state||'todo'});break;
   case 'edit-task':showModal('edit-task',{id});break;
   case 'new-section':showModal('new-section');break;
   case 'edit-section':showModal('edit-section',{id});break;
   case 'new-milestone':showModal('new-milestone');break;
   case 'edit-milestone':showModal('edit-milestone',{id});break;
   case 'new-expense':showModal('new-expense');break;
   case 'edit-expense':showModal('edit-expense',{id});break;
   case 'toggle-step':{const c=p.checklists.find(x=>x.id===id);await api('/api/checklist/'+id,'PATCH',{done:!c.done});closeModal();await updateAfter(p.id);showModal('edit-task',{id:c.task_id});break;}
   case 'add-step':{const input=$('#step-title');const name=input?.value.trim();if(!name){toast('Escribe el nombre del paso.','info');break;}await api('/api/tasks/'+id+'/checklist','POST',{title:name});closeModal();await updateAfter(p.id);showModal('edit-task',{id});break;}
   case 'delete-step':{if(!window.confirm('¿Eliminar este paso para los dos?'))break;const c=p.checklists.find(x=>x.id===id);await api('/api/checklist/'+id,'DELETE');closeModal();await updateAfter(p.id);showModal('edit-task',{id:c.task_id});break;}
   case 'new-event':showModal('new-event');break;
   case 'edit-event':showModal('edit-event',{id});break;
   case 'new-link':showModal('new-link');break;
   case 'new-file':showModal('new-file');break;
   case 'password':showModal('password');break;
   case 'close-modal':if(ev.target.classList.contains('modal-overlay')||!el.classList.contains('modal-overlay'))closeModal();break;
   case 'quick-task':{const t=p.tasks.find(x=>x.id===id);await api('/api/tasks/'+id,'PATCH',{state:t.state==='done'?'todo':'done',revision:t.revision});await updateAfter(p.id);toast('Tarea actualizada.');break;}
   case 'delete-item':{
    if(!window.confirm('¿Eliminar este elemento de forma permanente para ambos?'))break;
    await api(`/api/${el.dataset.kind}/${id}`,'DELETE');S.modal=null;await updateAfter(p.id);toast('Elemento eliminado.');break;
   }
   case 'delete-project':{
    if(!window.confirm(`¿Mover «${p.title}» a la papelera? Ambos podréis recuperarlo desde Ajustes.`))break;
    await api('/api/projects/'+p.id,'DELETE');S.modal=null;await loadDash();nav(p.space);toast('Proyecto movido a la papelera.');break;
   }
   case 'save-ai':{
    if(!S.aiResult)return;
    const title=window.prompt('Título de la nota',S.aiResult.type==='mockup'?'Mockup generado con IA':'Resultado IA · '+S.aiResult.type);if(!title)return;
    await api(`/api/projects/${p.id}/sections`,'POST',{title,content:S.aiResult.content});S.aiResult=null;await updateAfter(p.id);S.tab='notes';render();toast('Resultado añadido a las notas.');break;
   }
   case 'download-mockup':{
    if(!S.aiResult)return;const blob=new Blob([cleanHtml(S.aiResult.content)],{type:'text/html;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='mockup-'+p.title.normalize('NFD').replace(/[^a-zA-Z0-9-]/g,'-').slice(0,40)+'.html';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);break;
   }
   case 'logout':await api('/api/logout','POST');S.stream?.close();S.me=null;S.dash=null;renderLogin();break;
  }
 }catch(ex){toast(ex.message,'error');}
}
function bindGlobal(){} // Eventos delegados instalados una sola vez en attachEvents.
function attachEvents(){
 document.addEventListener('click',async ev=>{
  const navEl=ev.target.closest('[data-nav]');if(navEl){ev.preventDefault();if(navEl.dataset.nav==='knowledge')S.knowledgeData=await api('/api/knowledge');if(navEl.dataset.nav==='intelligence')S.analyticsData=await api('/api/analytics?space='+encodeURIComponent(S.analyticsSpace==='all'?'':S.analyticsSpace));if(navEl.dataset.nav==='guardian')S.guardianData=await api('/api/guardian/report');if(navEl.dataset.nav==='notices')S.noticeData=await api('/api/notifications');if(navEl.dataset.nav==='archives')S.archiveData=await api('/api/archives');if(navEl.dataset.nav==='trash')S.trashData=await api('/api/trash');nav(navEl.dataset.nav);return;}
  const tab=ev.target.closest('[data-tab]');if(tab){ev.preventDefault();S.tab=tab.dataset.tab;render();return;}
  const filter=ev.target.closest('[data-filter]');if(filter){S.filter=filter.dataset.filter;render();return;}
  const action=ev.target.closest('[data-action]');if(action){ev.preventDefault();await handleAction(action,ev);return;}
  const projectEl=ev.target.closest('[data-project]');if(projectEl?.dataset.project){ev.preventDefault();await openProject(projectEl.dataset.project);return;}
  if(ev.target.closest('#sidebar')===null&&$('#sidebar')?.classList.contains('mobile-open'))$('#sidebar')?.classList.remove('mobile-open');
 });
 document.addEventListener('input',ev=>{if(ev.target.id==='project-search'){S.query=ev.target.value;renderCards();}});
 document.addEventListener('change',ev=>{if(ev.target.name==='space'&&S.modal?.type==='new-project'){const sel=$('#modal-form [name=template]');if(sel)sel.innerHTML=options(templates[ev.target.value]||templates.work,'blank');}});
 document.addEventListener('submit',async ev=>{
  if(ev.target.id==='modal-form'){ev.preventDefault();await saveModal(ev.target);return;}
  if(ev.target.id==='search-form'){
   ev.preventDefault();const q=new FormData(ev.target).get('q');try{S.searchResults=await api('/api/search?q='+encodeURIComponent(q));render();}catch(ex){toast(ex.message,'error');}return;
  }
  if(ev.target.id==='comment-form'){
   ev.preventDefault();const val=ev.target.elements.content.value.trim();if(!val)return;const btn=ev.target.querySelector('button');btn.disabled=true;
   try{await api(`/api/projects/${S.project.id}/comments`,'POST',{content:val});await updateAfter(S.project.id);toast('Mensaje compartido.');}catch(ex){toast(ex.message,'error');btn.disabled=false;}return;
  }
  if(ev.target.id==='ai-form'){
   ev.preventDefault();const btn=ev.target.querySelector('button'),fd=new FormData(ev.target);btn.disabled=true;btn.innerHTML=I('refresh',17)+' Generando…';
   S.aiType=fd.get('type');S.aiPrompt=fd.get('prompt');
   try{const r=await api(`/api/projects/${S.project.id}/ai`,'POST',{type:S.aiType,prompt:S.aiPrompt});S.aiResult=r;render();if(r.type==='mockup'&&$('#mockup-frame'))$('#mockup-frame').srcdoc=cleanHtml(r.content);toast('Resultado generado. Puedes guardarlo como nota.');}
   catch(ex){toast(ex.message,'error');btn.disabled=false;btn.innerHTML=I('spark',17)+' Generar con IA';}return;
  }
  if(ev.target.id==='ai-import'){
   ev.preventDefault();const fd=new FormData(ev.target),content=String(fd.get('content')||'').trim();if(!content)return;
   try{await api(`/api/projects/${S.project.id}/sections`,'POST',{title:String(fd.get('title')||'').trim()||'Ideas importadas de IA',content});await updateAfter(S.project.id);S.tab='notes';render();toast('Ideas importadas a las notas.');}catch(ex){toast(ex.message,'error');}return;
  }
 });
 document.addEventListener('dragstart',ev=>{const card=ev.target.closest('[data-drag]');if(card){ev.dataTransfer.setData('text/plain',card.dataset.drag);ev.dataTransfer.effectAllowed='move';}});
 document.addEventListener('dragover',ev=>{const col=ev.target.closest('[data-drop]');if(col){ev.preventDefault();col.classList.add('drag-over');}});
 document.addEventListener('dragleave',ev=>{const col=ev.target.closest('[data-drop]');if(col&&!col.contains(ev.relatedTarget))col.classList.remove('drag-over');});
 document.addEventListener('drop',async ev=>{const col=ev.target.closest('[data-drop]');if(!col)return;ev.preventDefault();col.classList.remove('drag-over');const id=ev.dataTransfer.getData('text/plain');if(!id)return;try{await api('/api/tasks/'+id,'PATCH',{state:col.dataset.drop,revision:S.project.tasks.find(x=>x.id===id).revision});await updateAfter(S.project.id);toast('Tarea movida y sincronizada.');}catch(ex){toast(ex.message,'error');}});
 document.addEventListener('keydown',ev=>{if(ev.key==='Escape'&&S.modal)closeModal();});
}
async function start(){attachEvents();try{const r=await api('/api/me');if(!r.user){if(!r.configured)renderSetup(r.setupAvailable);else renderLogin();return;}S.me=r.user;await loadDash();conn();render();}
 catch(ex){console.error(ex);$('#app').innerHTML=`<div class="startup-error"><h2>No se pudo conectar con vuestro servidor</h2><p>${e(ex.message)}</p><button class="btn primary" onclick="location.reload()">Reintentar</button></div>`;}}
start();
